import type { ЯзыкиРегиона } from "../core";

/** Названия и описания мест на zh, ko, de, fr, ja, tr, ar. */
export const ЯЗЫКИ_БУХАРЫ: ЯзыкиРегиона = {
  "bx-poikalon": {
    zh: { name: "波伊·卡扬建筑群", desc: "布哈拉老城的主广场，名字意为“伟大者的脚下”。三座建筑环绕着它：1127年的卡扬宣礼塔；1514年的卡扬聚礼清真寺——中亚最大的清真寺之一，庭院可容纳上万名礼拜者；以及对面带绿松石色穹顶的米里·阿拉布经学院。建筑群是联合国教科文组织世界遗产“布哈拉历史中心”的一部分。广场全天开放：早上来欣赏柔和的光线，天黑后来看泛光照明。" },
    ko: { name: "포이 칼론 단지", desc: "옛 부하라의 중심 광장으로, 이름은 ‘위대한 이의 발치’라는 뜻입니다. 세 건물이 광장을 둘러쌉니다. 1127년의 칼론 미나렛, 마당에 최대 1만 명이 예배할 수 있었던 중앙아시아 최대급의 1514년 칼론 금요 모스크, 그리고 맞은편 청록색 돔의 미르 아랍 마드라사입니다. 유네스코 세계유산 ‘부하라 역사 지구’의 일부입니다. 광장은 언제나 열려 있으니 부드러운 빛의 아침과 조명이 켜지는 밤에 오세요." },
    de: { name: "Ensemble Poi-Kalon", desc: "Der Hauptplatz des alten Buchara; der Name bedeutet „Zu Füßen des Großen“. Drei Bauten rahmen ihn: das Kalon-Minarett von 1127, die Kalon-Freitagsmoschee von 1514 – eine der größten Zentralasiens, in deren Hof bis zu zehntausend Gläubige beteten – und gegenüber die Mir-i-Arab-Medrese mit türkisfarbenen Kuppeln. Das Ensemble gehört zum UNESCO-Welterbe Historisches Zentrum von Buchara. Der Platz ist jederzeit zugänglich: morgens für weiches Licht, nach Einbruch der Dunkelheit für die Beleuchtung." },
    fr: { name: "Ensemble Poï-Kalian", desc: "La grande place du vieux Boukhara ; son nom signifie « Au pied du Grand ». Trois édifices l'encadrent : le minaret Kalian de 1127, la mosquée du vendredi Kalian de 1514 – l'une des plus grandes d'Asie centrale, dont la cour accueillait jusqu'à dix mille fidèles – et, en face, la médersa Mir-i-Arab aux coupoles turquoise. L'ensemble fait partie du centre historique de Boukhara inscrit à l'UNESCO. La place est accessible à toute heure : venez le matin pour la lumière douce et le soir pour les illuminations." },
    ja: { name: "ポイ・カラン建築群", desc: "旧ブハラの中央広場で、名前は「偉大なるものの足元」を意味します。三つの建物が広場を囲みます。1127年のカラン・ミナレット、中庭に1万人もの礼拝者が入れた中央アジア最大級の1514年のカラン金曜モスク、そして向かいのターコイズのドームをもつミル・アラブ・メドレセです。ユネスコ世界遺産「ブハラ歴史地区」の一部。広場はいつでも入れます。柔らかな光の朝と、ライトアップされる夜がおすすめです。" },
    tr: { name: "Poyi Kalan Külliyesi", desc: "Eski Buhara'nın ana meydanı; adı “Büyük Olanın Ayağında” demektir. Üç yapı onu çevreler: 1127 tarihli Kalan Minaresi, avlusu on bine kadar cemaat alan, Orta Asya'nın en büyüklerinden 1514 tarihli Kalan Cuma Camii ve karşısında turkuaz kubbeli Mir-i Arap Medresesi. Külliye UNESCO listesindeki Buhara Tarihi Merkezi'nin parçasıdır. Meydan her saat açıktır: yumuşak ışık için sabah, ışıklandırma için akşam gelin." },
    ar: { name: "مجمع بوي كلان", desc: "الساحة الرئيسية في بخارى القديمة، ويعني اسمها «عند قدم العظيم». تحيط بها ثلاثة مبانٍ: مئذنة كلان من عام 1127، ومسجد كلان الجامع من عام 1514 – من أكبر مساجد آسيا الوسطى، وكان فناؤه يتسع لعشرة آلاف مصلٍّ – وقبالتهما مدرسة مير عرب بقبابها الفيروزية. المجمع جزء من المركز التاريخي لبخارى المدرج في قائمة اليونسكو. الساحة مفتوحة في كل الأوقات: تعال صباحًا للضوء الناعم ومساءً للإضاءة." },
  },
  "bx-kalonminaret": {
    zh: { name: "卡扬宣礼塔", desc: "布哈拉的象征：一座高约46米的砖砌宣礼塔，建于1127年喀喇汗王朝统治者阿尔斯兰汗时期。塔身向上收窄，由一道道花纹砖带环绕，塔顶灯亭下方是该地区最早的蓝色釉面。传说成吉思汗摧毁全城时下令保留了这座塔。后来，死囚曾被从塔顶抛下，因此它又被称为“死亡之塔”。不能登塔，但从波伊·卡扬广场仰望景色震撼。" },
    ko: { name: "칼론 미나렛", desc: "부하라의 상징으로, 1127년 카라한 왕조의 통치자 아르슬란 칸 시대에 세워진 높이 약 46m의 벽돌 미나렛입니다. 탑신은 위로 갈수록 가늘어지며 무늬 벽돌 띠로 감싸여 있고, 꼭대기 등탑 아래에는 이 지역 최초의 푸른 유약이 있습니다. 전설에 따르면 칭기즈칸은 도시를 파괴하면서도 이 탑은 남기라고 명했습니다. 훗날 사형수를 꼭대기에서 떨어뜨려 ‘죽음의 탑’이라 불리기도 했습니다. 오를 수는 없지만 포이 칼론 광장에서 보는 모습이 압도적입니다." },
    de: { name: "Kalon-Minarett", desc: "Das Wahrzeichen Bucharas: ein etwa 46 Meter hohes Ziegelminarett, 1127 unter dem Karachaniden Arslan Khan erbaut. Der Schaft verjüngt sich nach oben und ist von Bändern aus gemustertem Mauerwerk umgeben; unter der Laternenrotunde sitzt die früheste blaue Glasur der Region. Der Legende nach ließ Dschingis Khan es verschonen, obwohl er die Stadt zerstörte. Später wurden Verurteilte von der Spitze gestürzt, daher der Name „Turm des Todes“. Besteigen ist nicht erlaubt, doch der Blick vom Poi-Kalon-Platz ist überwältigend." },
    fr: { name: "Minaret Kalian", desc: "Le symbole de Boukhara : un minaret de brique d'environ 46 mètres, élevé en 1127 sous le souverain karakhanide Arslan Khan. Le fût s'affine vers le haut et s'enroule de bandes de briques à motifs ; sous la lanterne se trouve la plus ancienne glaçure bleue de la région. La légende veut que Gengis Khan l'ait épargné alors qu'il détruisait la ville. Plus tard, on précipitait les condamnés du sommet, d'où son surnom de « tour de la mort ». On ne peut pas y monter, mais la vue depuis la place Poï-Kalian est saisissante." },
    ja: { name: "カラン・ミナレット", desc: "ブハラの象徴で、1127年にカラハン朝の君主アルスラン・ハンの時代に建てられた高さ約46mのれんがのミナレットです。塔身は上へいくほど細くなり、模様れんがの帯に包まれ、頂上の灯籠部の下にはこの地方で最も古い青い釉薬があります。伝説では、チンギス・ハンは町を破壊しながらもこの塔は残すよう命じたといいます。のちに罪人が頂上から突き落とされたことから「死の塔」とも呼ばれました。登ることはできませんが、ポイ・カラン広場からの眺めは圧巻です。" },
    tr: { name: "Kalan Minaresi", desc: "Buhara'nın simgesi: 1127'de Karahanlı hükümdarı Arslan Han döneminde yapılan yaklaşık 46 metre yüksekliğinde tuğla minare. Gövdesi yukarı doğru incelir ve desenli tuğla şeritlerle sarılıdır; fener kısmının altında bölgenin en eski mavi sırı bulunur. Rivayete göre Cengiz Han şehri yıkarken minarenin korunmasını emretti. Sonraları mahkûmlar tepesinden atıldığı için “Ölüm Kulesi” diye anıldı. Çıkmak yasaktır, ama Poyi Kalan meydanından görüntüsü büyüleyicidir." },
    ar: { name: "مئذنة كلان", desc: "رمز بخارى: مئذنة من الطوب بارتفاع نحو 46 مترًا، بُنيت عام 1127 في عهد الحاكم القراخاني أرسلان خان. يضيق جسمها نحو الأعلى وتلتف حوله أشرطة من الطوب المزخرف، وتحت الفانوس العلوي أقدم طلاء أزرق في المنطقة. تقول الأسطورة إن جنكيز خان أمر بالإبقاء عليها حين دمّر المدينة. وفي ما بعد كان المحكومون يُلقَون من قمتها، فسُميت «برج الموت». الصعود ممنوع، لكن المنظر من ساحة بوي كلان مذهل." },
  },
  "bx-mirarab": {
    zh: { name: "米里·阿拉布经学院", desc: "卡扬清真寺对面带两座绿松石色穹顶的经学院，建于1535–1536年。它与被称为“米里·阿拉布”的谢赫阿卜杜拉·亚曼尼有关，他是乌拜杜拉汗的导师；两人都葬在北穹顶下的墓室里。这是苏联时期少数被允许继续办学的经学院之一，至今仍是一所宗教学校。游客只能进入门厅，所以请在广场上欣赏门楼和穹顶，并穿着得体。" },
    ko: { name: "미르 아랍 마드라사", desc: "칼론 모스크 맞은편에 있는 두 개의 청록색 돔을 가진 마드라사로, 1535~1536년에 지어졌습니다. 우바이둘라 칸의 스승이자 ‘미르 아랍’이라 불린 셰이흐 압둘라 야마니와 관련이 있으며, 두 사람 모두 북쪽 돔 아래 묘실에 묻혀 있습니다. 소련 시대에도 운영이 허락된 몇 안 되는 마드라사 중 하나로 지금도 종교 학교입니다. 방문객은 입구 현관까지만 들어갈 수 있으니 광장에서 정문과 돔을 감상하고 단정하게 입으세요." },
    de: { name: "Mir-i-Arab-Medrese", desc: "Eine Medrese mit zwei türkisfarbenen Kuppeln gegenüber der Kalon-Moschee, erbaut 1535–1536. Sie ist mit Scheich Abdullah Yamani verbunden, genannt Mir-i-Arab, dem Lehrer Ubaidullah Khans; beide ruhen in der Grabkammer unter der Nordkuppel. Sie war eine der wenigen Medresen, die in Sowjetzeiten arbeiten durften, und ist bis heute eine religiöse Schule. Besucher dürfen nur den Eingangsvorraum betreten – bewundern Sie Portal und Kuppeln vom Platz aus und kleiden Sie sich zurückhaltend." },
    fr: { name: "Médersa Mir-i-Arab", desc: "Une médersa à deux coupoles turquoise face à la mosquée Kalian, construite en 1535–1536. Elle est liée au cheikh Abdallah Yamani, dit Mir-i-Arab, maître d'Oubaïdoullah Khan ; tous deux reposent dans la chambre funéraire sous la coupole nord. Ce fut l'une des rares médersas autorisées à fonctionner sous les Soviétiques, et c'est toujours une école religieuse. Les visiteurs ne peuvent entrer que dans le vestibule : admirez portail et coupoles depuis la place et habillez-vous correctement." },
    ja: { name: "ミル・アラブ・メドレセ", desc: "カラン・モスクの向かいに建つ二つのターコイズのドームをもつメドレセで、1535～1536年に建てられました。ウバイドゥッラー・ハンの師で「ミル・アラブ」と呼ばれたシェイフ・アブドゥッラー・ヤマニーゆかりの建物で、二人とも北のドームの下の墓室に眠ります。ソ連時代にも運営を許された数少ないメドレセの一つで、今も宗教学校です。見学できるのは入口の玄関ホールまでなので、門とドームは広場から眺め、控えめな服装で。" },
    tr: { name: "Mir-i Arap Medresesi", desc: "Kalan Camii'nin karşısında, iki turkuaz kubbeli, 1535–1536'da yapılan medrese. Ubeydullah Han'ın hocası, Mir-i Arap diye anılan Şeyh Abdullah Yemeni ile ilişkilidir; ikisi de kuzey kubbenin altındaki türbe odasında yatar. Sovyet döneminde çalışmasına izin verilen az sayıdaki medreseden biriydi ve hâlâ bir din okuludur. Ziyaretçiler yalnızca giriş holüne girebilir; taç kapıyı ve kubbeleri meydandan seyredin ve kapalı giyinin." },
    ar: { name: "مدرسة مير عرب", desc: "مدرسة بقبتين فيروزيتين قبالة مسجد كلان، بُنيت بين 1535 و1536. ترتبط بالشيخ عبد الله اليماني المعروف بمير عرب، معلم عبيد الله خان، وكلاهما مدفون في حجرة الضريح تحت القبة الشمالية. كانت من المدارس القليلة التي سُمح لها بالعمل في العهد السوفيتي، ولا تزال مدرسة دينية. لا يُسمح للزوار إلا بدخول الدهليز، فتأمّل البوابة والقباب من الساحة وارتدِ ملابس محتشمة." },
  },
  "bx-ark": {
    zh: { name: "阿尔克城堡", desc: "布哈拉的内城——建在约四公顷人工土丘上的“城中之城”。几个世纪以来，从古代的布哈拉统治者到最后一位埃米尔都住在这里，直到1920年红军攻城时城堡遭到严重破坏。一条坡道通向18世纪的城门；城内有1712年的聚礼清真寺、埃米尔接见宾客的觐见庭院、昔日的居室以及地区历史博物馆展览。城墙前是雷吉斯坦广场，昔日用于阅兵和处决。" },
    ko: { name: "아르크 요새", desc: "약 4헥타르의 인공 언덕 위에 세워진 부하라의 성채로, ‘도시 안의 도시’입니다. 고대 부하르 후다트부터 마지막 에미르까지 수 세기 동안 통치자들이 이곳에 살았으나, 1920년 붉은 군대의 공격으로 크게 파괴되었습니다. 경사로를 오르면 18세기의 성문이 있고, 안에는 1712년의 금요 모스크, 에미르가 손님을 맞던 알현 마당, 옛 거처, 지역 역사 전시가 있습니다. 성벽 앞에는 열병식과 처형이 열리던 레기스탄 광장이 있습니다." },
    de: { name: "Festung Ark", desc: "Bucharas Zitadelle ist eine Stadt in der Stadt auf einem künstlichen Hügel von etwa vier Hektar. Jahrhundertelang lebten hier die Herrscher, von den alten Buchar-Chudat bis zum letzten Emir, bis die Festung 1920 beim Sturm der Roten Armee schwer beschädigt wurde. Eine Rampe führt zu einem Tor aus dem 18. Jahrhundert; drinnen liegen die Freitagsmoschee von 1712, der Thronhof, in dem der Emir Gäste empfing, frühere Gemächer und Museumsausstellungen zur Regionalgeschichte. Vor den Mauern liegt der Registan, einst Ort von Paraden und Hinrichtungen." },
    fr: { name: "Forteresse de l'Arche", desc: "La citadelle de Boukhara est une ville dans la ville, sur un tertre artificiel d'environ quatre hectares. Les souverains y vécurent des siècles durant, des anciens Boukhar Khoudat jusqu'au dernier émir, jusqu'à ce que la forteresse soit gravement endommagée lors de l'assaut de l'Armée rouge en 1920. Une rampe mène à une porte du XVIIIe siècle ; à l'intérieur : la mosquée du vendredi de 1712, la cour du trône où l'émir recevait, d'anciens appartements et des expositions sur l'histoire régionale. Devant les murs s'étend le Registan, jadis lieu de parades et d'exécutions." },
    ja: { name: "アルク城", desc: "約4ヘクタールの人工の丘の上に築かれたブハラの城塞で、「町の中の町」です。古代のブハール・フダートから最後のアミールまで、何世紀にもわたって支配者が暮らしましたが、1920年の赤軍の攻撃で大きく損壊しました。坂道を上ると18世紀の門があり、内部には1712年の金曜モスク、アミールが客を迎えた謁見の庭、かつての居室、地域の歴史展示があります。城壁の前には、かつて閲兵式や処刑が行われたレギスタン広場が広がります。" },
    tr: { name: "Ark Kalesi", desc: "Buhara'nın iç kalesi, yaklaşık dört hektarlık yapay bir tepe üzerinde “şehir içinde bir şehir”. Eski Buhar Hudatlarından son emire kadar hükümdarlar yüzyıllarca burada yaşadı; kale 1920'de Kızıl Ordu saldırısında ağır hasar gördü. Bir rampa 18. yüzyıldan kalma bir kapıya çıkar; içeride 1712 tarihli Cuma camii, emirin misafirlerini kabul ettiği taht avlusu, eski odalar ve bölge tarihine dair müze sergileri vardır. Surların önünde bir zamanlar geçit törenleri ve idamların yapıldığı Registan meydanı uzanır." },
    ar: { name: "قلعة آرك", desc: "قلعة بخارى مدينة داخل المدينة على تلّ صناعي مساحته نحو أربعة هكتارات. عاش فيها الحكام قرونًا، من بخار خداة القدماء حتى آخر أمير، إلى أن تضررت بشدة خلال هجوم الجيش الأحمر عام 1920. يصعد ممر منحدر إلى بوابة من القرن الثامن عشر، وفي الداخل مسجد الجمعة من عام 1712، وفناء العرش حيث كان الأمير يستقبل ضيوفه، وحجرات قديمة، ومعروضات متحفية عن تاريخ المنطقة. وأمام الأسوار ساحة ريغستان التي كانت تُقام فيها العروض والإعدامات." },
  },
  "bx-labihauz": {
    zh: { name: "利亚比豪兹建筑群", desc: "布哈拉老城最热闹的地方：一座环绕着石砌水池（豪兹）的广场，水池于1620年奉大臣纳迪尔·迪万别吉之命开挖。名字意为“水池边”。水池周围是库克尔达什经学院（1568–1569年）以及纳迪尔·迪万别吉的修道院和经学院，古老桑树的树荫下是茶馆和咖啡馆。附近有骑着毛驴的霍贾·纳斯尔丁铜像，他是无数笑话的主角，也是人们合影的热点。夜晚广场灯火通明，是开始或结束散步的好地方。" },
    ko: { name: "랴비하우즈 단지", desc: "옛 부하라에서 가장 활기찬 곳으로, 1620년 재상 나디르 디반베기의 명으로 판 석조 연못(하우즈)을 둘러싼 광장입니다. 이름은 ‘연못가’라는 뜻입니다. 연못 주위로 쿠켈다시 마드라사(1568~1569)와 나디르 디반베기의 하나카, 마드라사가 있고, 오래된 뽕나무 그늘 아래 찻집과 카페가 있습니다. 근처에는 수많은 우스갯소리의 주인공인 나귀 탄 호자 나스레딘 청동상이 있습니다. 밤에는 광장에 불이 켜져 산책의 시작이나 끝으로 좋습니다." },
    de: { name: "Ensemble Labi-Hauz", desc: "Der lebendigste Ort des alten Buchara: ein Platz um einen steingefassten Hauz, einen Teich, der 1620 auf Befehl des Wesirs Nadir Divanbegi angelegt wurde. Der Name bedeutet „am Teich“. Der Teich wird von der Kukeldasch-Medrese (1568–1569) sowie Nadir Divanbegis Chanaka und Medrese gerahmt, Teehäuser und Cafés liegen im Schatten alter Maulbeerbäume. Daneben steht ein bronzener Nasreddin Hodscha auf seinem Esel, Held unzähliger Witze und Fotos. Abends ist der Platz beleuchtet – ein natürlicher Start- oder Endpunkt für einen Spaziergang." },
    fr: { name: "Ensemble Lyabi-Khaouz", desc: "Le lieu le plus animé du vieux Boukhara : une place autour d'un khaouz bordé de pierre, un bassin creusé en 1620 sur ordre du vizir Nadir Divan-Beghi. Le nom signifie « au bord du bassin ». Le bassin est encadré par la médersa Koukeldach (1568–1569) et la khanqah et la médersa de Nadir Divan-Beghi, tandis que maisons de thé et cafés s'abritent sous de vieux mûriers. À côté, un Nasreddin Hodja de bronze sur son âne, héros d'innombrables histoires et photos. La place est illuminée le soir et marque naturellement le début ou la fin d'une promenade." },
    ja: { name: "ラビ・ハウズ建築群", desc: "旧ブハラで最もにぎやかな場所で、1620年に宰相ナディル・ディヴァンベギの命で掘られた石積みの池（ハウズ）を囲む広場です。名前は「池のほとり」を意味します。池の周りにはクケルダシュ・メドレセ（1568～1569年）、ナディル・ディヴァンベギのハナカとメドレセが並び、古い桑の木陰にはチャイハナやカフェがあります。近くには数々の笑い話の主人公、ロバに乗ったホジャ・ナスレッディンの銅像があります。夜はライトアップされ、散策の始まりや終わりにぴったりです。" },
    tr: { name: "Labi Havuz Külliyesi", desc: "Eski Buhara'nın en canlı yeri: 1620'de vezir Nadir Divanbeyi'nin emriyle kazılan taş kenarlı bir havuzun etrafındaki meydan. Adı “havuz kenarı” demektir. Havuzu Kökeldaş Medresesi (1568–1569) ile Nadir Divanbeyi'nin hankahı ve medresesi çevreler; çayhaneler ve kafeler yaşlı dut ağaçlarının gölgesindedir. Yakınında sayısız fıkranın ve fotoğrafın kahramanı, eşeğinin üstündeki bronz Nasreddin Hoca heykeli durur. Meydan geceleri ışıklandırılır; bir yürüyüşe başlamak ya da bitirmek için doğal bir nokta." },
    ar: { name: "مجمع لبي حوض", desc: "أكثر الأماكن حيوية في بخارى القديمة: ساحة حول «حوض» مبطّن بالحجر، حُفر عام 1620 بأمر الوزير نادر ديوان بيكي. ويعني الاسم «على حافة الحوض». تحيط بالحوض مدرسة كوكلداش (1568–1569) وخانقاه نادر ديوان بيكي ومدرسته، وتقبع المقاهي وبيوت الشاي في ظل أشجار التوت المعمّرة. وبالقرب تمثال برونزي لجحا (خوجه نصر الدين) على حماره، بطل نوادر وصور لا تُحصى. تُضاء الساحة ليلًا، وهي بداية أو نهاية طبيعية لأي نزهة." },
  },
  "bx-nodirdevonbegi": {
    zh: { name: "纳迪尔·迪万别吉经学院", desc: "利亚比豪兹东侧的一座1622年经学院。它原本计划作为商队客栈，但应伊玛姆库利汗的意愿改成了经学院——所以它没有讲经清真寺。它的门楼很有名：马赛克上两只西牟鸟爪抓白鹿，飞向一个长着人脸的太阳，这在伊斯兰建筑中是大胆的图案，如今已成为布哈拉的标志。庭院里满是手工艺品店，晚上常举办配晚餐的民俗表演。" },
    ko: { name: "나디르 디반베기 마드라사", desc: "랴비하우즈 동쪽에 있는 1622년의 마드라사입니다. 원래 카라반사라이로 계획되었으나 이맘쿨리 칸의 뜻에 따라 마드라사가 되었기 때문에 강의용 모스크가 없습니다. 정문이 유명한데, 모자이크 속 두 마리 시무르그 새가 흰 사슴을 발톱에 쥐고 사람 얼굴을 한 태양을 향해 날아갑니다. 이슬람 건축에서는 대담한 이 그림은 부하라의 상징이 되었습니다. 안뜰에는 공예품 가게가 가득하고, 저녁에는 저녁 식사와 함께하는 민속 공연이 자주 열립니다." },
    de: { name: "Nadir-Divanbegi-Medrese", desc: "Eine Medrese von 1622 an der Ostseite des Labi-Hauz. Sie war als Karawanserei geplant, wurde aber auf Wunsch Imamquli Khans zur Medrese – deshalb fehlt eine Lehrmoschee. Berühmt ist das Portal: Im Mosaik tragen zwei Simurgh-Vögel weiße Hirschkühe in den Klauen und fliegen auf eine Sonne mit Menschengesicht zu – ein kühnes Motiv für islamische Architektur und heute ein Wahrzeichen Bucharas. Im Hof liegen Handwerksläden, abends gibt es oft Folkloreshows mit Abendessen." },
    fr: { name: "Médersa Nadir Divan-Beghi", desc: "Une médersa de 1622 sur le côté est du Lyabi-Khaouz. Prévue comme caravansérail, elle devint médersa par la volonté d'Imamqouli Khan – d'où l'absence de mosquée d'enseignement. Son portail est célèbre : dans la mosaïque, deux oiseaux Simorgh tiennent des biches blanches dans leurs serres et volent vers un soleil à visage humain, une image audacieuse pour l'architecture islamique devenue emblème de Boukhara. La cour est remplie de boutiques d'artisans, et le soir s'y tiennent souvent des spectacles folkloriques avec dîner." },
    ja: { name: "ナディル・ディヴァンベギ・メドレセ", desc: "ラビ・ハウズの東側に建つ1622年のメドレセです。隊商宿として計画されましたが、イマームクリー・ハンの意向でメドレセになったため、講義用のモスクがありません。門が有名で、モザイクには白い鹿を爪でつかんだ二羽のスィームルグが、人の顔をした太陽に向かって飛ぶ姿が描かれています。イスラム建築としては大胆な図柄で、今ではブハラの象徴です。中庭には工芸品店が並び、夜には食事付きの民俗ショーがよく開かれます。" },
    tr: { name: "Nadir Divanbeyi Medresesi", desc: "Labi Havuz'un doğu yakasında 1622 tarihli bir medrese. Kervansaray olarak planlanmış, ancak İmamkulu Han'ın isteğiyle medreseye dönüştürülmüştür – bu yüzden ders mescidi yoktur. Taç kapısı ünlüdür: mozaikte iki Simurg kuşu pençelerinde beyaz ceylanlar taşıyarak insan yüzlü bir güneşe doğru uçar; İslam mimarisi için cesur bu tasvir Buhara'nın simgesi olmuştur. Avlu zanaat dükkânlarıyla doludur, akşamları sık sık akşam yemekli folklor gösterileri yapılır." },
    ar: { name: "مدرسة نادر ديوان بيكي", desc: "مدرسة من عام 1622 على الجانب الشرقي من لبي حوض. خُطّط لها أن تكون خانًا للقوافل، لكنها صارت مدرسة بإرادة إمام قلي خان – ولذلك لا مسجد للدرس فيها. بوابتها شهيرة: في الفسيفساء طائرا «سيمرغ» يحملان في مخالبهما غزالين أبيضين ويطيران نحو شمس بوجه إنسان، وهي صورة جريئة في العمارة الإسلامية صارت رمزًا لبخارى. يمتلئ الفناء بمحال الحرفيين، وتُقام فيه مساءً غالبًا عروض فلكلورية مع العشاء." },
  },
  "bx-kukeldash": {
    zh: { name: "利亚比豪兹旁的库克尔达什经学院", desc: "中亚最大的经学院之一，宽敞庭院周围约有160间学生宿舍。它于1568–1569年由阿卜杜拉汗二世的乳兄弟、权臣库尔巴巴·库克尔达什出资建造。经学院在北面围合了利亚比豪兹建筑群；外墙饰有马赛克，雕花木门和格栅窗近看最美。苏联时期这里曾用作宿舍和档案馆，如今设有文化教育展览。" },
    ko: { name: "랴비하우즈의 쿠켈다시 마드라사", desc: "넓은 안뜰 주위에 약 160개의 학생 방이 있는 중앙아시아 최대급 마드라사입니다. 1568~1569년 압둘라 칸 2세의 젖형제이자 권세 있는 신하 쿨바바 쿠켈다시의 돈으로 지어졌습니다. 랴비하우즈 단지를 북쪽에서 감싸며, 정면에는 마욜리카가 있고 조각된 문과 판자라 격자창은 가까이에서 볼 때 가장 아름답습니다. 소련 시대에는 기숙사와 기록 보관소로 쓰였고, 지금은 문화·교육 전시가 열립니다." },
    de: { name: "Kukeldasch-Medrese am Labi-Hauz", desc: "Eine der größten Medresen Zentralasiens mit etwa 160 Studentenzellen um einen weiten Hof. Sie wurde 1568–1569 auf Kosten von Kulbaba Kukeldasch erbaut, Milchbruder und mächtiger Höfling Abdullah Khans II. Die Medrese schließt das Labi-Hauz-Ensemble nach Norden ab; die Fassade trägt Majolika, und die geschnitzten Türen und Pandschara-Gitter sieht man am besten aus der Nähe. In Sowjetzeiten diente sie als Wohnheim und Archiv, heute zeigt sie kulturelle und pädagogische Ausstellungen." },
    fr: { name: "Médersa Koukeldach du Lyabi-Khaouz", desc: "L'une des plus grandes médersas d'Asie centrale, avec environ 160 cellules d'étudiants autour d'une vaste cour. Elle fut bâtie en 1568–1569 aux frais de Koulbaba Koukeldach, frère de lait et puissant courtisan d'Abdoullah Khan II. La médersa ferme l'ensemble du Lyabi-Khaouz au nord ; sa façade porte de la majolique, et ses portes sculptées et ses grilles panjara se découvrent de près. Sous les Soviétiques, elle servit de foyer et d'archives ; elle accueille aujourd'hui des expositions culturelles et éducatives." },
    ja: { name: "ラビ・ハウズのクケルダシュ・メドレセ", desc: "広い中庭の周りに約160の学生房をもつ中央アジア最大級のメドレセです。1568～1569年、アブドゥッラー・ハン2世の乳兄弟で権勢をふるった廷臣クルババ・クケルダシュの費用で建てられました。ラビ・ハウズ建築群を北側で閉じ、正面にはマジョリカ、彫刻の扉やパンジャラの格子は近くで見るといっそう見事です。ソ連時代には寮や文書館として使われ、現在は文化・教育の展示が行われています。" },
    tr: { name: "Labi Havuz'daki Kökeldaş Medresesi", desc: "Geniş bir avlu çevresinde yaklaşık 160 öğrenci hücresiyle Orta Asya'nın en büyük medreselerinden biri. 1568–1569'da II. Abdullah Han'ın sütkardeşi ve güçlü saray adamı Kulbaba Kökeldaş'ın parasıyla yapıldı. Medrese Labi Havuz külliyesini kuzeyden kapatır; cephesinde mayolika vardır, oymalı kapılar ve pencere kafesleri yakından en güzel görünür. Sovyet döneminde yurt ve arşiv olarak kullanıldı; bugün kültür ve eğitim sergilerine ev sahipliği yapar." },
    ar: { name: "مدرسة كوكلداش عند لبي حوض", desc: "من أكبر مدارس آسيا الوسطى، فيها نحو 160 حجرة للطلاب حول فناء فسيح. بُنيت بين 1568 و1569 على نفقة قولبابا كوكلداش، أخي عبد الله خان الثاني في الرضاعة وأحد كبار رجال بلاطه. تغلق المدرسة مجمع لبي حوض من الشمال، وعلى واجهتها خزف مزجج، وأبوابها المنحوتة وشبابيكها المشبكة أجمل عن قرب. استُخدمت في العهد السوفيتي سكنًا وأرشيفًا، وتضم اليوم معارض ثقافية وتعليمية." },
  },
  "bx-chorminor": {
    zh: { name: "乔尔米诺尔", desc: "一座1807年的奇特建筑，四座小塔顶着绿松石色穹顶，因此得名“四座宣礼塔”。它是富商哈利夫·尼亚兹库尔所建经学院的门楼；经学院本身几乎已不复存在。这四座塔从来不是真正的宣礼塔，每座装饰各不相同——一个传说称这四种图案代表商人的四个女儿。它位于利亚比豪兹以东一个安静的街区：穿过马哈拉小巷步行前往。" },
    ko: { name: "초르 미노르", desc: "청록색 돔을 얹은 네 개의 작은 탑이 있는 1807년의 독특한 건물로, 그래서 ‘네 개의 미나렛’이라는 이름이 붙었습니다. 부유한 상인 할리프 니야즈쿨이 세운 마드라사의 문루이며, 마드라사 자체는 거의 남아 있지 않습니다. 탑들은 진짜 미나렛이 아니었고 장식도 모두 다릅니다. 한 전설에 따르면 네 가지 문양은 상인의 네 딸을 상징합니다. 랴비하우즈 동쪽 조용한 동네에 있으니 마할라 골목을 따라 걸어가 보세요." },
    de: { name: "Tschor Minor", desc: "Ein ungewöhnlicher Bau von 1807 mit vier kleinen Türmen unter türkisfarbenen Kuppeln, daher der Name „Vier Minarette“. Es ist das Torhaus einer Medrese, die der reiche Kaufmann Chalif Nijaskul erbauen ließ; die Medrese selbst ist fast verschwunden. Die Türme waren nie echte Minarette, und jeder ist anders verziert – einer Legende nach stehen die vier Muster für die vier Töchter des Kaufmanns. Er liegt in einem ruhigen Viertel östlich des Labi-Hauz: Gehen Sie durch die Gassen der Mahalla hin." },
    fr: { name: "Tchor Minor", desc: "Un édifice insolite de 1807 à quatre tourelles coiffées de coupoles turquoise, d'où son nom de « Quatre minarets ». C'est le portail d'une médersa bâtie par le riche marchand Khalif Niyazkoul ; la médersa elle-même a presque disparu. Les tours ne furent jamais de vrais minarets, et chacune est décorée différemment – une légende veut que les quatre motifs représentent les quatre filles du marchand. Il se trouve dans un quartier calme à l'est du Lyabi-Khaouz : allez-y à pied par les ruelles de la mahalla." },
    ja: { name: "チョル・ミノル", desc: "ターコイズのドームをいただく四つの小塔をもつ1807年の珍しい建物で、そこから「四つのミナレット」と呼ばれます。裕福な商人ハリフ・ニヤズクルが建てたメドレセの門楼で、メドレセ本体はほとんど残っていません。塔は本物のミナレットではなく、装飾もそれぞれ異なります。ある伝説では、四つの模様は商人の四人の娘を表しているといいます。ラビ・ハウズの東の静かな街区にあるので、マハッラの路地を歩いて訪れましょう。" },
    tr: { name: "Çor Minor", desc: "Turkuaz kubbelerle örtülü dört küçük kulesiyle 1807 tarihli alışılmadık bir yapı; adı da “Dört Minare”dir. Zengin tüccar Halife Niyazkul'un yaptırdığı bir medresenin kapı yapısıdır; medresenin kendisi neredeyse yok olmuştur. Kuleler hiçbir zaman gerçek minare değildi ve her biri farklı süslenmiştir – bir efsaneye göre dört desen tüccarın dört kızını simgeler. Labi Havuz'un doğusunda sakin bir mahallededir: mahalle sokaklarından yürüyerek gidin." },
    ar: { name: "تشور مينور", desc: "مبنى غير مألوف من عام 1807 بأربعة أبراج صغيرة تعلوها قباب فيروزية، ومن هنا اسمه «المآذن الأربع». هو بوابة مدرسة بناها التاجر الثري خليف نيازقول، أما المدرسة نفسها فقد زالت تقريبًا. لم تكن الأبراج مآذن حقيقية قط، ولكل منها زخرفتها – وتقول أسطورة إن النقوش الأربعة ترمز إلى بنات التاجر الأربع. يقع في حيّ هادئ شرق لبي حوض: امشِ إليه عبر أزقة المحلة." },
  },
  "bx-samanids": {
    zh: { name: "萨曼王朝陵墓", desc: "中亚伊斯兰建筑最古老的遗迹之一：萨曼王朝的家族陵墓，建于10世纪初，与伊斯玛仪·萨曼尼有关。这座带穹顶的小立方体完全用烧砖砌成，砌法如同编织的篮子，墙面随着一天中光影的移动而变化。几个世纪以来它被埋在土下，因此得以保存；直到20世纪30年代才被清理出来。它位于萨曼公园内，靠近查什马·阿尤布。" },
    ko: { name: "사만 왕조 영묘", desc: "중앙아시아 이슬람 건축의 가장 오래된 유적 중 하나로, 10세기 초에 지어진 사만 왕조의 가족 묘이며 이스마일 사마니와 관련이 있습니다. 돔을 얹은 작은 정육면체 건물은 전부 구운 벽돌로 바구니를 엮은 듯한 무늬로 쌓아 올려, 하루 동안 빛과 그림자가 움직이며 벽의 모습이 변합니다. 수백 년 동안 흙에 묻혀 있었던 덕분에 보존되었고, 1930년대에야 드러났습니다. 차슈마 아유브 근처 사만 공원 안에 있습니다." },
    de: { name: "Samaniden-Mausoleum", desc: "Eines der ältesten Denkmäler islamischer Architektur in Zentralasien: das Familiengrab der Samaniden, im frühen 10. Jahrhundert erbaut und mit Ismail Samani verbunden. Der kleine Kuppelwürfel ist ganz aus gebrannten Ziegeln gemauert, gelegt wie ein geflochtener Korb, sodass sich die Wände mit Licht und Schatten im Tageslauf verändern. Jahrhundertelang lag er unter Erde begraben, was ihn rettete; erst in den 1930er-Jahren wurde er freigelegt. Er steht im Samaniden-Park nahe Tschaschma-Ayub." },
    fr: { name: "Mausolée des Samanides", desc: "L'un des plus anciens monuments de l'architecture islamique d'Asie centrale : le tombeau familial des Samanides, construit au début du Xe siècle et associé à Ismaïl Samani. Le petit cube à coupole est entièrement bâti en briques cuites disposées comme une vannerie tressée, si bien que les murs changent au fil de la lumière et des ombres. Il resta enfoui sous la terre pendant des siècles, ce qui le sauva, et ne fut dégagé que dans les années 1930. Il se trouve dans le parc Samanide, près de Tchachma-Ayoub." },
    ja: { name: "サーマーン廟", desc: "中央アジアのイスラム建築で最も古い遺構の一つで、10世紀初めに建てられたサーマーン朝の一族の墓、イスマーイール・サーマーニーゆかりの霊廟です。ドームをいただく小さな立方体はすべて焼成れんがで、編んだかごのような模様に積まれ、一日の光と影の移ろいとともに壁の表情が変わります。何世紀も土に埋もれていたおかげで守られ、1930年代になってようやく掘り出されました。チャシュマ・アユブ近くのサーマーン公園にあります。" },
    tr: { name: "Samaniler Türbesi", desc: "Orta Asya İslam mimarisinin en eski anıtlarından biri: 10. yüzyıl başında yapılan ve İsmail Samani ile ilişkilendirilen Samani hanedanının aile türbesi. Kubbeli küçük küp tamamen pişmiş tuğladan, örülmüş bir sepet gibi desenle örülmüştür; bu yüzden duvarlar gün boyunca ışık ve gölgeyle değişir. Yüzyıllarca toprak altında kaldı, onu kurtaran da bu oldu; ancak 1930'larda gün yüzüne çıkarıldı. Çeşme-i Eyüp yakınındaki Samani Parkı'ndadır." },
    ar: { name: "ضريح السامانيين", desc: "من أقدم معالم العمارة الإسلامية في آسيا الوسطى: الضريح العائلي للأسرة السامانية، بُني مطلع القرن العاشر ويرتبط باسم إسماعيل الساماني. المكعب الصغير ذو القبة مبني كليًا من الآجر المحروق المرصوف كسلة منسوجة، فتتبدل الجدران مع حركة الضوء والظل خلال النهار. ظل مدفونًا تحت التراب قرونًا، وهذا ما أنقذه، ولم يُكشف إلا في ثلاثينيات القرن الماضي. يقع في حديقة السامانيين قرب جشمه أيوب." },
  },
  "bx-chashmaayub": {
    zh: { name: "查什马·阿尤布陵墓", desc: "一座建在圣泉之上的建筑，名字意为“约伯之泉”。传说先知阿尤布（约伯）用手杖击地，干旱之地便涌出了泉水。建筑从12世纪开始形成，14世纪帖木儿时期由花剌子模工匠重建，所以其中一个大厅有布哈拉罕见的圆锥形尖顶。内部是布哈拉水博物馆，有古老水池和运河的模型。旁边是伊玛目布哈里纪念馆和萨曼公园。" },
    ko: { name: "차슈마 아유브 영묘", desc: "성스러운 샘 위에 세운 건물로, 이름은 ‘욥의 샘’이라는 뜻입니다. 전설에 따르면 예언자 아유브(욥)가 지팡이로 땅을 치자 메마른 땅에서 물이 솟았다고 합니다. 건물은 12세기부터 형성되었고 14세기 티무르 시대에 호라즘 장인들이 다시 지어, 한 홀에 부하라에서는 드문 원뿔형 천막 돔이 있습니다. 안에는 옛 연못과 운하 모형을 갖춘 부하라 물 박물관이 있습니다. 옆에는 이맘 알부하리 기념관과 사만 공원이 있습니다." },
    de: { name: "Mausoleum Tschaschma-Ayub", desc: "Ein Bau über einer heiligen Quelle; der Name bedeutet „Hiobs Brunnen“. Der Legende nach schlug der Prophet Ayub (Hiob) mit seinem Stab auf den Boden, und im trockenen Land sprudelte Wasser hervor. Der Bau wuchs ab dem 12. Jahrhundert und wurde im 14. unter Timur von Meistern aus Choresm umgebaut – daher trägt ein Saal eine in Buchara seltene konische Zeltkuppel. Drinnen ist Bucharas Wassermuseum mit Modellen der alten Teiche und Kanäle. Nebenan liegen die Gedenkstätte Imam al-Buchari und der Samaniden-Park." },
    fr: { name: "Mausolée de Tchachma-Ayoub", desc: "Un édifice bâti sur une source sacrée ; son nom signifie « Puits de Job ». La légende raconte que le prophète Ayoub (Job) frappa le sol de son bâton et que l'eau jaillit dans cette terre aride. Le bâtiment s'est formé à partir du XIIe siècle et fut reconstruit au XIVe sous Timour par des maîtres du Khorezm, d'où la coupole conique en tente, rare à Boukhara, sur l'une des salles. À l'intérieur, le musée de l'eau de Boukhara présente des maquettes des anciens bassins et canaux. À côté : le mémorial de l'imam al-Boukhari et le parc Samanide." },
    ja: { name: "チャシュマ・アユブ廟", desc: "聖なる泉の上に建つ建物で、名前は「ヨブの泉」を意味します。伝説では、預言者アユーブ（ヨブ）が杖で地を打つと、乾いた土地に水が湧き出たといいます。建物は12世紀から形づくられ、14世紀にティムールの時代にホラズムの職人が建て直したため、ホールの一つにブハラでは珍しい円錐形の天幕型ドームがあります。内部は古い池や運河の模型を展示するブハラ水の博物館です。隣にはイマーム・ブハーリー記念碑とサーマーン公園があります。" },
    tr: { name: "Çeşme-i Eyüp Türbesi", desc: "Kutsal bir kaynağın üzerine yapılmış bir bina; adı “Eyüp'ün Pınarı” demektir. Rivayete göre Eyüp Peygamber asasıyla yere vurmuş ve bu kurak toprakta su fışkırmıştır. Yapı 12. yüzyıldan itibaren şekillendi ve 14. yüzyılda Timur döneminde Harezmli ustalarca yeniden inşa edildi; bu yüzden bir salonda Buhara'da nadir görülen konik çadır kubbe vardır. İçinde eski havuzların ve kanalların maketleriyle Buhara su müzesi bulunur. Yanında İmam Buhari anıtı ve Samani Parkı yer alır." },
    ar: { name: "ضريح جشمه أيوب", desc: "مبنى قائم على نبع مقدس، ويعني اسمه «بئر أيوب». تقول الأسطورة إن النبي أيوب ضرب الأرض بعصاه فتفجّر الماء في هذه الأرض الجافة. تشكّل المبنى منذ القرن الثاني عشر، وأعاد بناءه حرفيون من خوارزم في القرن الرابع عشر في عهد تيمور، ولذا تعلو إحدى قاعاته قبة مخروطية خيمية نادرة في بخارى. وفي داخله متحف المياه في بخارى بنماذج للأحواض والقنوات القديمة. وبجواره نصب الإمام البخاري وحديقة السامانيين." },
  },
  "bx-magokiattori": {
    zh: { name: "马戈基·阿塔里清真寺", desc: "布哈拉现存最古老的清真寺。它位于比如今街面低几米的洼地中——因此得名“马戈基”，意为“坑中的”，而“阿塔里”则让人想起昔日环绕它的草药和药剂商贩集市。12世纪的南门楼布满精美的雕刻赤陶装饰，20世纪30年代的发掘还在其下发现了更古老建筑的遗迹。如今这里是布哈拉地毯博物馆，周围仍矗立着古老的商业穹顶。" },
    ko: { name: "마고키 아토리 모스크", desc: "부하라에 남아 있는 가장 오래된 모스크입니다. 지금의 길보다 몇 미터 아래 움푹한 곳에 있어 ‘구덩이 속’이라는 뜻의 ‘마고키’라 불리고, ‘아토리’는 한때 주변에 있던 약초와 약재 상인들의 시장을 떠올리게 합니다. 12세기 남쪽 정문은 섬세한 테라코타 조각으로 덮여 있으며, 1930년대 발굴에서 그 아래 훨씬 오래된 건축물의 흔적이 드러났습니다. 지금은 부하라 카펫 박물관이 있고 주변에는 옛 상업 돔들이 서 있습니다." },
    de: { name: "Moschee Magoki-Attori", desc: "Die älteste erhaltene Moschee Bucharas. Sie liegt in einer Senke mehrere Meter unter dem heutigen Straßenniveau – daher „Magoki“, „in der Grube“ –, während „Attori“ an den Basar der Kräuter- und Arzneihändler erinnert, der sie einst umgab. Das Südportal aus dem 12. Jahrhundert ist mit feiner geschnitzter Terrakotta bedeckt, und Grabungen in den 1930er-Jahren legten darunter Reste viel älterer Bauten frei. Heute beherbergt sie Bucharas Teppichmuseum, ringsum stehen die alten Handelskuppeln." },
    fr: { name: "Mosquée Magoki-Attari", desc: "La plus ancienne mosquée conservée de Boukhara. Elle se trouve dans un creux plusieurs mètres sous la rue actuelle – d'où « magoki », « dans la fosse » –, tandis que « attari » rappelle le bazar des marchands d'herbes et de remèdes qui l'entourait autrefois. Le portail sud du XIIe siècle est couvert d'une délicate terre cuite sculptée, et des fouilles des années 1930 ont révélé dessous les restes de constructions bien plus anciennes. Elle abrite aujourd'hui le musée des tapis de Boukhara, entourée des anciennes coupoles marchandes." },
    ja: { name: "マゴキ・アッタリ・モスク", desc: "ブハラに現存する最古のモスクです。今の道路より数メートル低いくぼ地にあることから「穴の中の」を意味する「マゴキ」と呼ばれ、「アッタリ」はかつて周りにあった薬草や薬売りのバザールを思い起こさせます。12世紀の南門は繊細なテラコッタ彫刻で覆われ、1930年代の発掘ではその下からさらに古い建物の跡が見つかりました。現在はブハラの絨毯博物館で、周囲には古い商業ドームが立ち並びます。" },
    tr: { name: "Magok-i Attari Camii", desc: "Buhara'nın ayakta kalan en eski camii. Bugünkü sokak seviyesinin birkaç metre altında bir çukurda durur – adındaki “magok” yani “çukurdaki” buradan gelir –, “attari” ise bir zamanlar çevresini saran şifalı ot ve ilaç satıcıları pazarını hatırlatır. 12. yüzyıldan kalma güney taç kapısı ince oymalı pişmiş toprakla kaplıdır; 1930'lardaki kazılar altında çok daha eski yapıların kalıntılarını ortaya çıkardı. Bugün Buhara halı müzesine ev sahipliği yapar; çevresinde eski çarşı kubbeleri durur." },
    ar: { name: "مسجد مغاكي عطاري", desc: "أقدم مسجد باقٍ في بخارى. يقع في منخفض يقل عدة أمتار عن مستوى الشارع الحالي – ومن هنا «مغاكي» أي «في الحفرة» – بينما تذكّر كلمة «عطاري» بسوق العطارين وباعة الأعشاب والأدوية الذي كان يحيط به. البوابة الجنوبية من القرن الثاني عشر مكسوة بزخارف دقيقة من الطين المحروق المنحوت، وكشفت حفريات الثلاثينيات تحته بقايا مبانٍ أقدم بكثير. ويضم اليوم متحف السجاد في بخارى، وحوله القباب التجارية القديمة." },
  },
  "bx-ulugbek": {
    zh: { name: "兀鲁伯经学院", desc: "1417年的经学院，是帖木儿之孙、著名天文学家兀鲁伯所建三座经学院中最早的一座（另两座在撒马尔罕和吉日杜万）。入口上方的铭文写道：“追求知识是每个穆斯林男女的义务。”建筑简朴而优雅，有马赛克板、雕花木门以及环绕庭院的两层宿舍回廊。16世纪阿卜杜拉汗二世时期曾翻修。内部有一个小型博物馆展览；对面是阿卜杜拉齐兹汗经学院。" },
    ko: { name: "울루그베크 마드라사", desc: "1417년의 마드라사로, 티무르의 손자이자 유명한 천문학자 울루그베크가 세운 세 마드라사 가운데 가장 이른 것입니다(나머지는 사마르칸트와 기즈두반에 있음). 입구 위에는 ‘지식을 추구하는 것은 모든 무슬림 남녀의 의무’라는 글귀가 새겨져 있습니다. 절제되었지만 우아한 건물로, 마욜리카 패널, 조각된 문, 안뜰을 둘러싼 2층 회랑의 방들이 있습니다. 16세기 압둘라 칸 2세 때 보수되었습니다. 안에는 작은 박물관 전시가 있고, 맞은편에 압둘아지즈 칸 마드라사가 있습니다." },
    de: { name: "Ulugh-Beg-Medrese", desc: "Eine Medrese von 1417, die früheste der drei, die Ulugh Beg erbauen ließ, Timurs Enkel und berühmter Astronom (die anderen stehen in Samarkand und Gijduvon). Über dem Eingang steht: „Das Streben nach Wissen ist die Pflicht jedes Muslims und jeder Muslimin.“ Das Gebäude ist zurückhaltend, aber elegant, mit Majolikatafeln, geschnitzten Türen und zweistöckigen Zellengalerien um den Hof. Im 16. Jahrhundert wurde es unter Abdullah Khan II. erneuert. Drinnen gibt es eine kleine Ausstellung; gegenüber steht die Abdulaziz-Khan-Medrese." },
    fr: { name: "Médersa Ouloug Beg", desc: "Une médersa de 1417, la plus ancienne des trois bâties par Ouloug Beg, petit-fils de Timour et célèbre astronome (les autres sont à Samarcande et à Guijdouvan). Au-dessus de l'entrée, une inscription dit : « La quête du savoir est le devoir de tout musulman et de toute musulmane. » Le bâtiment est sobre mais élégant, avec panneaux de majolique, portes sculptées et galeries de cellules sur deux niveaux autour de la cour. Il fut rénové au XVIe siècle sous Abdoullah Khan II. À l'intérieur, une petite exposition ; en face se dresse la médersa Abdoulaziz Khan." },
    ja: { name: "ウルグベク・メドレセ", desc: "1417年のメドレセで、ティムールの孫で著名な天文学者ウルグベクが建てた三つのメドレセのうち最も古いものです（他はサマルカンドとギジュドゥヴァン）。入口の上には「知識を求めることはすべてのムスリムの男女の務めである」と刻まれています。マジョリカのパネル、彫刻の扉、中庭を囲む2階建ての学生房の回廊をもつ、控えめながら優美な建物です。16世紀にアブドゥッラー・ハン2世のもとで改修されました。内部には小さな展示があり、向かいにはアブドゥルアジズ・ハン・メドレセが建っています。" },
    tr: { name: "Uluğ Bey Medresesi", desc: "1417 tarihli medrese; Timur'un torunu ve ünlü astronom Uluğ Bey'in yaptırdığı üç medresenin en eskisi (diğerleri Semerkant ve Gijduvan'dadır). Girişin üzerindeki yazıtta “İlim öğrenmek her Müslüman erkek ve kadına farzdır” yazar. Bina sade ama zariftir: mayolika panolar, oymalı kapılar ve avlunun çevresinde iki katlı hücre revakları. 16. yüzyılda II. Abdullah Han döneminde yenilendi. İçeride küçük bir müze sergisi vardır; karşısında Abdülaziz Han Medresesi durur." },
    ar: { name: "مدرسة أولوغ بيك", desc: "مدرسة من عام 1417، وهي أقدم المدارس الثلاث التي بناها أولوغ بيك، حفيد تيمور والفلكي الشهير (والأخريان في سمرقند وغجدوان). وفوق المدخل نقش يقول: «طلب العلم فريضة على كل مسلم ومسلمة». المبنى بسيط لكنه أنيق، فيه ألواح من الخزف المزجج وأبواب منحوتة وأروقة حجرات من طابقين حول الفناء. جُدّد في القرن السادس عشر في عهد عبد الله خان الثاني. وفي الداخل معرض متحفي صغير، وقبالته مدرسة عبد العزيز خان." },
  },
  "bx-abdulazizkhan": {
    zh: { name: "阿卜杜拉齐兹汗经学院", desc: "1652年的经学院，与兀鲁伯经学院相对——是阿斯特拉罕王朝统治者阿卜杜拉齐兹汗对其伟大前辈的回应。这是布哈拉装饰最华丽的建筑之一，有多彩马赛克、钟乳石状的穆卡纳斯拱顶、鸟类图案以及借鉴中国和印度艺术的纹样。装饰从未完成，因为工程未竣工汗就被推翻了。内部是木雕博物馆，展示布哈拉工匠制作的门、柱和日用器物。" },
    ko: { name: "압둘아지즈 칸 마드라사", desc: "울루그베크 마드라사와 마주한 1652년의 마드라사로, 아슈타르한 왕조의 통치자 압둘아지즈 칸이 위대한 선대에 내놓은 답이었습니다. 다채색 모자이크, 종유석 같은 무카르나스 천장, 새 그림, 중국과 인도 미술에서 빌린 문양으로 부하라에서 가장 화려하게 장식된 건물 중 하나입니다. 공사가 끝나기 전에 칸이 폐위되어 장식은 끝내 완성되지 못했습니다. 안에는 부하라 장인들이 만든 문, 기둥, 생활용품을 전시하는 목공예 박물관이 있습니다." },
    de: { name: "Abdulaziz-Khan-Medrese", desc: "Eine Medrese von 1652 gegenüber der Ulugh-Beg-Medrese – die Antwort des Aschtarchaniden Abdulaziz Khan an seinen großen Vorgänger. Sie gehört zu den am prächtigsten geschmückten Bauten Bucharas, mit vielfarbigem Mosaik, Muqarnas-Stalaktitengewölben, Vogeldarstellungen und Motiven aus chinesischer und indischer Kunst. Der Schmuck wurde nie vollendet, da der Khan vor Abschluss der Arbeiten gestürzt wurde. Drinnen zeigt ein Holzschnitzmuseum Türen, Säulen und Hausrat Bucharaer Meister." },
    fr: { name: "Médersa Abdoulaziz Khan", desc: "Une médersa de 1652 face à la médersa Ouloug Beg – la réponse du souverain achtarkhanide Abdoulaziz Khan à son illustre prédécesseur. C'est l'un des édifices les plus richement décorés de Boukhara : mosaïque polychrome, voûtes à muqarnas, figures d'oiseaux et motifs empruntés aux arts chinois et indien. Le décor ne fut jamais achevé, le khan ayant été déposé avant la fin des travaux. À l'intérieur, un musée du bois sculpté présente portes, colonnes et objets usuels des artisans de Boukhara." },
    ja: { name: "アブドゥルアジズ・ハン・メドレセ", desc: "ウルグベク・メドレセと向かい合う1652年のメドレセで、アシュタルハン朝の君主アブドゥルアジズ・ハンが偉大な先人に示した答えでした。多色のモザイク、鍾乳石のようなムカルナスの天井、鳥の図像、中国やインドの美術から取り入れた文様など、ブハラで最も華やかに装飾された建物の一つです。工事が終わる前にハンが廃位されたため、装飾は未完のままです。内部はブハラの職人による扉や柱、日用品を展示する木彫博物館になっています。" },
    tr: { name: "Abdülaziz Han Medresesi", desc: "Uluğ Bey Medresesi'nin karşısında 1652 tarihli medrese – Astarhanlı hükümdar Abdülaziz Han'ın büyük selefine cevabı. Çok renkli mozaikleri, mukarnas tavanları, kuş tasvirleri ve Çin ile Hint sanatından alınan motifleriyle Buhara'nın en gösterişli süslenmiş yapılarından biridir. Han, işler bitmeden tahttan indirildiği için süsleme hiç tamamlanmadı. İçeride Buharalı ustaların kapılarını, sütunlarını ve ev eşyalarını sergileyen bir ahşap oymacılığı müzesi vardır." },
    ar: { name: "مدرسة عبد العزيز خان", desc: "مدرسة من عام 1652 قبالة مدرسة أولوغ بيك – ردّ الحاكم الأشترخاني عبد العزيز خان على سلفه العظيم. وهي من أغنى مباني بخارى زخرفة: فسيفساء متعددة الألوان، وأقبية مقرنصات، وصور طيور، وزخارف مقتبسة من الفنين الصيني والهندي. لم تكتمل الزخرفة قط، إذ خُلع الخان قبل انتهاء العمل. وفي الداخل متحف للحفر على الخشب يعرض أبوابًا وأعمدة وأدوات منزلية صنعها حرفيو بخارى." },
  },
  "bx-zargaron": {
    zh: { name: "托基·扎尔加龙商业穹顶", desc: "布哈拉最大的商业穹顶，建于1569–1570年两条商业街交汇处。名字意为“珠宝商的穹顶”，得名于在此工作的金银匠。中央大穹顶周围环绕着店铺上方的小穹顶，光线从鼓座上的窗户射入。如今这里仍有珠宝和纪念品店——是欣赏布哈拉金线刺绣、首饰和刀具的好地方。从穹顶处可以看到卡扬宣礼塔。" },
    ko: { name: "토키 자르가론 상업 돔", desc: "두 시장 거리가 만나는 곳에 1569~1570년 세워진 부하라 최대의 상업 돔입니다. 이름은 이곳에서 일하던 금은세공사들에서 따온 ‘보석상의 돔’이라는 뜻입니다. 중앙 돔을 가게 위 작은 돔들이 둘러싸고, 빛은 돔 아래 둥근 벽의 창으로 들어옵니다. 지금도 보석과 기념품 가게가 있어 부하라 금사 자수, 장신구, 칼을 구경하기 좋습니다. 돔에서 칼론 미나렛이 보입니다." },
    de: { name: "Handelskuppel Toki Zargaron", desc: "Die größte Handelskuppel Bucharas, 1569–1570 an der Kreuzung zweier Marktstraßen erbaut. Der Name bedeutet „Kuppel der Juweliere“, nach den Gold- und Silberschmieden, die hier arbeiteten. Die Mittelkuppel ist von kleineren Kuppeln über den Läden umgeben, Licht fällt durch Fenster im Tambour. Schmuck- und Souvenirläden handeln hier bis heute – ein guter Ort für Bucharaer Goldstickerei, Schmuck und Messer. Von der Kuppel aus sieht man das Kalon-Minarett." },
    fr: { name: "Coupole marchande Toki Zargaron", desc: "La plus grande des coupoles marchandes de Boukhara, bâtie en 1569–1570 au croisement de deux rues commerçantes. Son nom signifie « coupole des joailliers », d'après les orfèvres qui y travaillaient. La coupole centrale est entourée de petites coupoles au-dessus des boutiques, la lumière entrant par les fenêtres du tambour. Bijouteries et boutiques de souvenirs y commercent toujours – l'endroit idéal pour voir la broderie d'or de Boukhara, bijoux et couteaux. Depuis la coupole, on aperçoit le minaret Kalian." },
    ja: { name: "タキ・ザルガロン（宝石商のドーム）", desc: "二つの市場通りが交わる場所に1569～1570年に建てられた、ブハラ最大の交易ドームです。名前は、ここで働いた金銀細工師にちなむ「宝石商のドーム」。中央の大ドームを店の上の小さなドームが囲み、ドラム部の窓から光が差し込みます。今も宝飾品や土産物の店が並び、ブハラの金糸刺繍やアクセサリー、ナイフを見るのにぴったりです。ドームからはカラン・ミナレットが見えます。" },
    tr: { name: "Toki Zergeran Çarşı Kubbesi", desc: "İki çarşı sokağının kesiştiği yerde 1569–1570'te yapılan Buhara'nın en büyük çarşı kubbesi. Adı, burada çalışan altın ve gümüş ustalarından dolayı “Kuyumcular Kubbesi” demektir. Merkezi kubbeyi dükkânların üzerindeki küçük kubbeler çevreler, ışık kasnaktaki pencerelerden girer. Kuyumcu ve hediyelik eşya dükkânları hâlâ burada ticaret yapar – Buhara altın işlemesi, takılar ve bıçaklar için iyi bir yer. Kubbeden Kalan Minaresi görünür." },
    ar: { name: "قبة تاقي زرغران التجارية", desc: "أكبر القباب التجارية في بخارى، بُنيت بين 1569 و1570 عند تقاطع شارعين تجاريين. يعني اسمها «قبة الصاغة» نسبةً إلى صائغي الذهب والفضة الذين عملوا هنا. تحيط بالقبة المركزية قباب صغيرة فوق الدكاكين، ويدخل الضوء من نوافذ الرقبة. لا تزال محال المجوهرات والتذكارات تعمل هنا – مكان جيد لرؤية تطريز بخارى بالذهب والحلي والسكاكين. ومن القبة تُرى مئذنة كلان." },
  },
  "bx-telpakfurushon": {
    zh: { name: "托基·捷尔帕克富鲁雄商业穹顶", desc: "16世纪的商业穹顶，名为“帽商的穹顶”：昔日这里出售花帽、皮帽和缠头巾。它覆盖着五条街道的交汇处，因此平面呈不规则多边形，中央大厅周围挤满了带小穹顶的店铺。如今这里出售书籍、乐器、纺织品和纪念品。旁边是半埋在地下的马戈基·库尔帕清真寺，步行几分钟即到波伊·卡扬。" },
    ko: { name: "토키 텔팍푸루숀 상업 돔", desc: "‘모자 상인의 돔’이라 불린 16세기 상업 돔으로, 옛날에는 전통 모자, 털모자, 터번을 팔았습니다. 다섯 거리가 만나는 교차로를 덮고 있어 평면이 불규칙한 다각형이며, 중앙 홀 주위로 작은 돔을 얹은 가게들이 빼곡합니다. 지금은 책, 악기, 직물, 기념품을 팝니다. 옆에는 반쯤 땅에 묻힌 마고키 쿠르파 모스크가 있고, 포이 칼론까지 걸어서 몇 분입니다." },
    de: { name: "Handelskuppel Toki Telpak Furushon", desc: "Eine Handelskuppel aus dem 16. Jahrhundert, die „Kuppel der Hutverkäufer“: Hier wurden einst Käppchen, Pelzmützen und Turbane verkauft. Sie überdeckt eine Kreuzung von fünf Straßen, daher der unregelmäßige vieleckige Grundriss, mit kleinen Kuppelläden rund um die Mittelhalle. Heute gibt es Bücher, Musikinstrumente, Stoffe und Souvenirs. Daneben steht die halb versunkene Moschee Magoki-Kurpa, und bis zum Poi-Kalon sind es wenige Gehminuten." },
    fr: { name: "Coupole marchande Toki Telpak Fourouchon", desc: "Une coupole marchande du XVIe siècle, la « coupole des chapeliers » : on y vendait autrefois calottes, bonnets de fourrure et turbans. Elle couvre un carrefour de cinq rues, d'où son plan polygonal irrégulier, avec de petites boutiques à coupole serrées autour de la salle centrale. On y vend aujourd'hui livres, instruments de musique, textiles et souvenirs. À côté se trouve la mosquée semi-enterrée Magoki-Kourpa, et le Poï-Kalian est à quelques minutes à pied." },
    ja: { name: "タキ・テルパク・フルション（帽子商のドーム）", desc: "「帽子商のドーム」と呼ばれる16世紀の交易ドームで、かつては刺繍帽、毛皮帽、ターバンが売られていました。五本の通りが交わる交差点を覆っているため平面は不規則な多角形で、中央ホールの周りに小さなドームの店がひしめいています。今は本、楽器、織物、土産物を売っています。隣には半ば地中に埋もれたマゴキ・クルパ・モスクがあり、ポイ・カランまでは歩いて数分です。" },
    tr: { name: "Toki Telpakfuruşan Çarşı Kubbesi", desc: "16. yüzyıldan bir çarşı kubbesi, “Şapkacılar Kubbesi”: burada bir zamanlar takkeler, kürk şapkalar ve sarıklar satılırdı. Beş sokağın kavşağını örttüğü için düzensiz çokgen bir planı vardır; merkezi salonun çevresinde küçük kubbeli dükkânlar sıralanır. Bugün kitaplar, müzik aletleri, kumaşlar ve hediyelik eşyalar satılır. Yanında yarı gömülü Magok-i Kurpa Camii durur; Poyi Kalan birkaç dakikalık yürüyüş mesafesindedir." },
    ar: { name: "قبة تاقي تلباك فوروشون التجارية", desc: "قبة تجارية من القرن السادس عشر تُسمى «قبة باعة القلانس»: كانت تُباع فيها القلانس وقبعات الفرو والعمائم. تغطي تقاطع خمسة شوارع، لذا مخططها مضلّع غير منتظم، وتتزاحم حول قاعتها الوسطى دكاكين صغيرة بقباب. تُباع فيها اليوم الكتب والآلات الموسيقية والمنسوجات والتذكارات. وبجوارها مسجد مغاكي كورپه نصف المطمور، وبوي كلان على بعد دقائق سيرًا." },
  },
  "bx-sarrofon": {
    zh: { name: "托基·萨拉丰商业穹顶", desc: "16世纪的商业穹顶，离利亚比豪兹最近。名字意为“兑换商的穹顶”：萨拉夫们曾在这里为丝绸之路商人兑换各国钱币——堪称布哈拉的银行先驱。穹顶原本立在横跨老沙赫鲁德运河的桥边，这条运河为城中各水池供水。如今穹顶下是地毯、纺织品和纪念品店。是商业穹顶路线的便捷起点：萨拉丰—捷尔帕克富鲁雄—扎尔加龙。" },
    ko: { name: "토키 사라폰 상업 돔", desc: "랴비하우즈에서 가장 가까운 16세기 상업 돔입니다. 이름은 ‘환전상의 돔’이라는 뜻으로, 사라프들이 이곳에서 실크로드 상인들을 위해 여러 나라 동전을 바꿔 주었으니 부하라 은행의 선구자인 셈입니다. 돔은 도시의 연못에 물을 대던 옛 샤흐루드 운하의 다리 옆에 있었습니다. 지금은 카펫, 직물, 기념품 가게가 있습니다. 상업 돔 산책로 사라폰-텔팍푸루숀-자르가론의 첫 정거장으로 편리합니다." },
    de: { name: "Handelskuppel Toki Sarrafon", desc: "Eine Handelskuppel aus dem 16. Jahrhundert, die dem Labi-Hauz am nächsten liegt. Der Name bedeutet „Kuppel der Geldwechsler“: Hier saßen Sarrafs und tauschten Münzen vieler Länder für die Kaufleute der Seidenstraße – Bucharas Vorläufer einer Bank. Die Kuppel stand an einer Brücke über den alten Schahrud-Kanal, der die Teiche der Stadt speiste. Heute liegen unter ihren Gewölben Teppich-, Textil- und Souvenirläden. Ein guter erster Halt der Kuppelroute: Sarrafon, Telpak Furushon, Zargaron." },
    fr: { name: "Coupole marchande Toki Sarrafon", desc: "Une coupole marchande du XVIe siècle, la plus proche du Lyabi-Khaouz. Son nom signifie « coupole des changeurs » : les sarrafs y changeaient les monnaies de nombreux pays pour les marchands de la route de la soie – l'ancêtre boukhariote de la banque. La coupole se dressait près d'un pont sur l'ancien canal Chakhroud, qui alimentait les bassins de la ville. Ses voûtes abritent aujourd'hui des boutiques de tapis, textiles et souvenirs. Une première étape pratique de l'itinéraire des coupoles : Sarrafon, Telpak Fourouchon, Zargaron." },
    ja: { name: "タキ・サラフォン（両替商のドーム）", desc: "ラビ・ハウズに最も近い16世紀の交易ドームです。名前は「両替商のドーム」を意味し、サラフたちがここでシルクロードの商人のために各国の硬貨を両替していました。ブハラの銀行の先駆けです。ドームは町の池に水を供給した旧シャフルド運河の橋のそばに建っていました。今は絨毯、織物、土産物の店が入っています。サラフォン、テルパク・フルション、ザルガロンと巡る交易ドーム散策の最初の立ち寄り先に便利です。" },
    tr: { name: "Toki Sarrafan Çarşı Kubbesi", desc: "Labi Havuz'a en yakın, 16. yüzyıldan bir çarşı kubbesi. Adı “Sarraflar Kubbesi” demektir: sarraflar burada İpek Yolu tüccarları için birçok ülkenin paralarını bozardı – Buhara'nın bankacılık öncüsü. Kubbe, şehrin havuzlarını besleyen eski Şahrud kanalı üzerindeki bir köprünün yanında duruyordu. Bugün kemerlerinin altında halı, kumaş ve hediyelik eşya dükkânları vardır. Kubbeler rotasının kullanışlı ilk durağı: Sarrafan, Telpakfuruşan, Zergeran." },
    ar: { name: "قبة تاقي صرافون التجارية", desc: "قبة تجارية من القرن السادس عشر، وهي الأقرب إلى لبي حوض. يعني اسمها «قبة الصرافين»: كان الصرافون يجلسون هنا يبدّلون عملات بلدان كثيرة لتجار طريق الحرير – سلف البنك في بخارى. كانت القبة قائمة عند جسر فوق قناة شهرود القديمة التي كانت تغذي أحواض المدينة. وتضم أقبيتها اليوم محال السجاد والمنسوجات والتذكارات. محطة أولى مناسبة في مسار القباب: صرافون، ثم تلباك فوروشون، ثم زرغران." },
  },
  "bx-timabdullakhan": {
    zh: { name: "阿卜杜拉汗商廊", desc: "1577年阿卜杜拉汗二世时期在扎尔加龙和捷尔帕克富鲁雄两座穹顶之间修建的有顶市场。与十字路口的穹顶不同，“提姆”是一条狭长的廊道，中央有穹顶，两侧是店铺。这里过去出售丝绸和毛料；如今是布哈拉欣赏手工地毯和苏扎尼刺绣的最佳地点之一。厚厚的拱顶即使在盛夏也很凉爽，商贩们乐于讲解打结技法和染料。" },
    ko: { name: "압둘라 칸의 팀", desc: "1577년 압둘라 칸 2세 때 자르가론과 텔팍푸루숀 돔 사이에 지어진 지붕 덮인 시장입니다. 교차로의 돔과 달리 ‘팀’은 가운데 돔이 있고 양옆에 가게가 늘어선 길쭉한 회랑입니다. 예전에는 비단과 모직물을 팔았고, 지금은 부하라에서 수제 카펫과 수자니 자수를 보기 가장 좋은 곳 중 하나입니다. 두꺼운 둥근 천장 덕분에 한여름에도 시원하며, 상인들이 매듭법과 염료를 기꺼이 설명해 줍니다." },
    de: { name: "Tim Abdullah Khans", desc: "Eine überdachte Markthalle von 1577, unter Abdullah Khan II. zwischen den Kuppeln Zargaron und Telpak Furushon erbaut. Anders als die Kreuzungskuppeln ist ein Tim eine langgestreckte Galerie mit Mittelkuppel und Läden an den Seiten. Hier wurden Seide und Wollstoffe verkauft; heute ist es einer der besten Orte Bucharas für handgeknüpfte Teppiche und Susani-Stickereien. Die dicken Gewölbe halten es selbst in der Sommerhitze kühl, und die Händler erklären gern Knüpftechniken und Farbstoffe." },
    fr: { name: "Tim d'Abdoullah Khan", desc: "Une halle marchande couverte de 1577, bâtie sous Abdoullah Khan II entre les coupoles Zargaron et Telpak Fourouchon. Contrairement aux coupoles de carrefour, un tim est une galerie allongée avec une coupole centrale et des boutiques sur les côtés. On y vendait la soie et les lainages ; c'est aujourd'hui l'un des meilleurs endroits de Boukhara pour voir des tapis faits main et des broderies suzani. Ses voûtes épaisses le gardent frais même en plein été, et les vendeurs expliquent volontiers nœuds et teintures." },
    ja: { name: "アブドゥッラー・ハンのティム", desc: "1577年にアブドゥッラー・ハン2世のもとでザルガロンとテルパク・フルションの両ドームの間に建てられた屋根付き市場です。交差点のドームと違い、ティムは中央にドーム、両側に店が並ぶ細長い回廊です。かつては絹や毛織物が売られ、今ではブハラで手織りの絨毯やスザニ刺繍を見るのに最適な場所の一つです。厚いヴォールトのおかげで夏の暑さの中でも涼しく、売り手たちは結び方や染料について喜んで説明してくれます。" },
    tr: { name: "Abdullah Han Timi", desc: "II. Abdullah Han döneminde Zergeran ve Telpakfuruşan kubbeleri arasında yapılan 1577 tarihli kapalı çarşı. Kavşak kubbelerinin aksine tim, ortada kubbesi ve iki yanında dükkânları olan uzun bir galeridir. Burada ipek ve yünlü kumaş satılırdı; bugün Buhara'da el dokuması halıları ve suzani işlemelerini görmek için en iyi yerlerden biridir. Kalın tonozlar yaz sıcağında bile serinlik sağlar; satıcılar düğüm tekniklerini ve boyaları anlatmaktan hoşlanır." },
    ar: { name: "تيم عبد الله خان", desc: "سوق مسقوف من عام 1577، بُني في عهد عبد الله خان الثاني بين قبتي زرغران وتلباك فوروشون. وخلافًا لقباب التقاطعات، فالتيم رواق طويل بقبة في وسطه ودكاكين على جانبيه. كانت تُباع فيه الحرير والأقمشة الصوفية، وهو اليوم من أفضل الأماكن في بخارى لرؤية السجاد اليدوي وتطريز السوزاني. تحفظ أقبيته السميكة البرودة حتى في حر الصيف، ويشرح الباعة طرق العقد والأصباغ عن طيب خاطر." },
  },
  "bx-bolohauz": {
    zh: { name: "博洛豪兹清真寺", desc: "埃米尔们的聚礼清真寺，位于阿尔克城堡对面，1712年建于同名水池“上池”旁。埃米尔每逢周五从城堡步行来此做礼拜。它最引人注目的是20世纪初增建的高大廊台，由二十根纤细的雕花木柱支撑；柱子倒映在池水中仿佛加倍，因此清真寺有时被称为“四十柱”。廊台天花板色彩鲜艳。这是正在使用的清真寺：请穿着得体，礼拜时不要进入。" },
    ko: { name: "볼로하우즈 모스크", desc: "아르크 맞은편에 있는 에미르들의 금요 모스크로, 1712년 같은 이름의 연못 ‘윗연못’ 옆에 지어졌습니다. 에미르는 금요 예배를 위해 요새에서 이곳으로 걸어왔습니다. 백미는 20세기 초에 덧붙인, 가느다란 조각 목조 기둥 스무 개가 받치는 높은 아이반입니다. 기둥이 연못에 비쳐 두 배로 보이기 때문에 ‘마흔 기둥’ 모스크라고도 불립니다. 아이반 천장은 화려하게 채색되어 있습니다. 현재 예배하는 모스크이니 단정하게 입고 예배 중에는 들어가지 마세요." },
    de: { name: "Bolo-Hauz-Moschee", desc: "Die Freitagsmoschee der Emire gegenüber der Ark, 1712 am gleichnamigen Teich erbaut – dem „oberen Teich“. Der Emir ging zum Freitagsgebet von der Festung hierher. Ihr Glanzstück ist ein hoher Aiwan auf zwanzig schlanken geschnitzten Holzsäulen, Anfang des 20. Jahrhunderts angefügt; im Teich gespiegelt scheinen sie sich zu verdoppeln, weshalb die Moschee manchmal „Vierzig Säulen“ heißt. Die Aiwandecke ist farbenprächtig bemalt. Eine aktive Moschee: zurückhaltend kleiden und nicht während des Gebets betreten." },
    fr: { name: "Mosquée Bolo-Khaouz", desc: "La mosquée du vendredi des émirs face à l'Arche, bâtie en 1712 au bord du bassin du même nom – le « bassin d'en haut ». L'émir venait à pied de la forteresse pour la prière du vendredi. Sa splendeur est un haut aïvan sur vingt fines colonnes de bois sculpté, ajouté au début du XXe siècle ; reflétées dans le bassin, elles semblent doubler, d'où le surnom de « Quarante colonnes ». Le plafond de l'aïvan est peint de couleurs vives. Mosquée active : tenue correcte et pas de visite pendant la prière." },
    ja: { name: "ボロ・ハウズ・モスク", desc: "アルク城の向かいにあるアミールたちの金曜モスクで、1712年に同名の池「上の池」のそばに建てられました。アミールは金曜礼拝のため城からここへ歩いて通いました。見どころは20世紀初めに加えられた、20本の細い彫刻の木柱に支えられた高いアイヴァンです。柱が池に映って倍に見えることから「40本柱」のモスクとも呼ばれます。アイヴァンの天井は鮮やかに彩色されています。現役のモスクなので、控えめな服装で、礼拝中は入らないでください。" },
    tr: { name: "Bolo Havuz Camii", desc: "Ark'ın karşısında, emirlerin Cuma camii; 1712'de aynı adlı havuzun – “Yukarı Havuz”un – yanında yapıldı. Emir Cuma namazı için kaleden buraya yürürdü. En göz alıcı yanı, 20. yüzyıl başında eklenen, yirmi ince oymalı ahşap sütun üzerindeki yüksek eyvandır; havuzda yansıyınca sütunlar iki katına çıkmış gibi görünür, bu yüzden camiye bazen “Kırk Sütun” denir. Eyvan tavanı canlı renklerle boyalıdır. Faal bir camidir: kapalı giyinin ve namaz sırasında girmeyin." },
    ar: { name: "مسجد بولو حوض", desc: "مسجد الجمعة الخاص بالأمراء قبالة قلعة آرك، بُني عام 1712 بجانب الحوض الذي يحمل الاسم نفسه – «الحوض العلوي». كان الأمير يمشي إليه من القلعة لصلاة الجمعة. أبرز ما فيه إيوان عالٍ على عشرين عمودًا خشبيًا رشيقًا منحوتًا، أُضيف في مطلع القرن العشرين؛ وحين تنعكس الأعمدة في الحوض تبدو مضاعفة، ولذا يُسمى المسجد أحيانًا «الأربعين عمودًا». سقف الإيوان مزدان بألوان زاهية. إنه مسجد قائم: ارتدِ ملابس محتشمة ولا تدخل أثناء الصلاة." },
  },
  "bx-zindan": {
    zh: { name: "齐恩丹监狱博物馆", desc: "布哈拉埃米尔国18至19世纪的监狱，离阿尔克城堡几步之遥，如今是博物馆。牢房、枷锁、铁链和最臭名昭著的“臭虫坑”都保存了下来，犯人被用绳子吊放进这个深坑。据广为流传的记述，英国军官查尔斯·斯托达特和亚瑟·康诺利曾被关押在这里，1842年在阿尔克城堡前的广场上被处决。展览介绍了埃米尔国的审判与刑罚。博物馆不大，却令人印象深刻。" },
    ko: { name: "진단 감옥 박물관", desc: "아르크에서 몇 걸음 떨어진 18~19세기 부하라 에미르국의 감옥으로, 지금은 박물관입니다. 감방, 차꼬, 쇠사슬과 가장 악명 높은 ‘벌레 구덩이’가 남아 있는데, 죄수들을 밧줄로 이 깊은 구덩이에 내려보냈습니다. 널리 알려진 이야기에 따르면 영국 장교 찰스 스토다트와 아서 코놀리가 이곳에 갇혀 있다가 1842년 아르크 앞 광장에서 처형되었습니다. 전시는 에미르국의 재판과 형벌을 설명합니다. 작지만 강한 인상을 남깁니다." },
    de: { name: "Gefängnismuseum Zindan", desc: "Das Gefängnis des Emirats Buchara aus dem 18.–19. Jahrhundert, wenige Schritte von der Ark, heute ein Museum. Zellen, Stöcke, Ketten und sein berüchtigtstes Merkmal sind erhalten: eine tiefe „Wanzengrube“, in die Gefangene an einem Seil hinabgelassen wurden. Nach bekanntem Bericht wurden hier die britischen Offiziere Charles Stoddart und Arthur Conolly festgehalten, bevor man sie 1842 auf dem Platz vor der Ark hinrichtete. Die Ausstellung erklärt Gerichte und Strafen des Emirats. Klein, aber eindrücklich." },
    fr: { name: "Musée de la prison Zindan", desc: "La prison de l'émirat de Boukhara des XVIIIe–XIXe siècles, à quelques pas de l'Arche, aujourd'hui musée. Cellules, entraves, chaînes et sa partie la plus tristement célèbre subsistent : une profonde « fosse aux punaises » où l'on descendait les prisonniers au bout d'une corde. Selon le récit bien connu, les officiers britanniques Charles Stoddart et Arthur Conolly y furent détenus avant d'être exécutés sur la place devant l'Arche en 1842. L'exposition présente la justice et les châtiments de l'émirat. Petit, mais marquant." },
    ja: { name: "ズィンダン（牢獄博物館）", desc: "アルク城から数歩の18～19世紀のブハラ・アミール国の牢獄で、現在は博物館です。独房、足枷、鎖、そして最も悪名高い「虫の穴」が残っています。囚人は綱でこの深い穴に吊り下ろされました。よく知られた記録によれば、英国の将校チャールズ・ストッダートとアーサー・コノリーがここに囚われ、1842年にアルク前の広場で処刑されました。展示はアミール国の裁きと刑罰を紹介しています。小さいながら強い印象を残します。" },
    tr: { name: "Zindan Hapishane Müzesi", desc: "Ark'a birkaç adım mesafede, Buhara Emirliği'nin 18.–19. yüzyıl hapishanesi; bugün müze. Hücreler, tomruklar, zincirler ve en kötü şöhretli kısmı korunmuştur: mahkûmların iple indirildiği derin “tahtakurusu çukuru”. Bilinen anlatıya göre İngiliz subaylar Charles Stoddart ve Arthur Conolly burada tutulmuş, 1842'de Ark'ın önündeki meydanda idam edilmişlerdir. Sergi emirliğin yargısını ve cezalarını anlatır. Küçük ama güçlü bir izlenim bırakır." },
    ar: { name: "متحف سجن زندان", desc: "سجن إمارة بخارى من القرنين الثامن عشر والتاسع عشر، على بعد خطوات من آرك، وهو اليوم متحف. لا تزال الزنازين والمقاطر والسلاسل باقية، وأشهرها «حفرة البق» العميقة التي كان السجناء يُدلَّون إليها بحبل. وبحسب الرواية المعروفة، احتُجز هنا الضابطان البريطانيان تشارلز ستودارت وآرثر كونولي قبل إعدامهما في الساحة أمام آرك عام 1842. يشرح المعرض قضاء الإمارة وعقوباتها. متحف صغير لكنه يترك أثرًا قويًا." },
  },
  "bx-magokikurpa": {
    zh: { name: "马戈基·库尔帕清真寺", desc: "1637年的两层清真寺，紧邻捷尔帕克富鲁雄穹顶——是继马戈基·阿塔里之后布哈拉第二座“下沉”清真寺。它的底层几乎一半被几个世纪堆积的土层掩埋，所以要沿楼梯下去才能进入。“库尔帕”得名于制作被褥的街区。两层都覆盖着穹顶，其中一些是钟乳石拱顶，主穹顶高约二十米。传说它原本要建成聚礼清真寺，但因太小而成了街区清真寺。" },
    ko: { name: "마고키 쿠르파 모스크", desc: "텔팍푸루숀 돔 옆에 있는 1637년의 2층 모스크로, 마고키 아토리에 이은 부하라의 두 번째 ‘가라앉은’ 모스크입니다. 수백 년 쌓인 흙에 아래층이 거의 절반쯤 묻혀 있어 계단을 내려가야 들어갈 수 있습니다. ‘쿠르파’는 이불을 만들던 동네 이름에서 왔습니다. 두 층 모두 돔으로 덮였고 그중 일부는 종유석 천장이며, 주 돔은 약 20m 높이로 솟아 있습니다. 전설에 따르면 금요 모스크로 지으려 했으나 너무 작아 동네 모스크가 되었습니다." },
    de: { name: "Moschee Magoki-Kurpa", desc: "Eine zweistöckige Moschee von 1637 neben der Kuppel Telpak Furushon – Bucharas zweite „versunkene“ Moschee nach Magoki-Attori. Ihr Untergeschoss ist von jahrhundertelang angewachsenem Boden fast zur Hälfte verdeckt, sodass man über eine Treppe hinabsteigt. „Kurpa“ stammt vom Viertel, in dem Steppdecken gefertigt wurden. Beide Geschosse sind mit Kuppeln gedeckt, teils mit Stalaktitengewölben; die Hauptkuppel ragt etwa zwanzig Meter auf. Der Legende nach sollte sie Freitagsmoschee werden, erwies sich aber als zu klein und wurde Viertelsmoschee." },
    fr: { name: "Mosquée Magoki-Kourpa", desc: "Une mosquée à deux niveaux de 1637 à côté de la coupole Telpak Fourouchon – la seconde mosquée « enfouie » de Boukhara après Magoki-Attari. Son niveau inférieur est à moitié caché par des siècles de remblais, si bien qu'on y descend par un escalier. « Kourpa » vient du quartier où l'on fabriquait les couvertures piquées. Les deux niveaux sont couverts de coupoles, certaines à stalactites, et la coupole principale s'élève à une vingtaine de mètres. La légende dit qu'elle devait être une mosquée du vendredi mais, trop petite, devint mosquée de quartier." },
    ja: { name: "マゴキ・クルパ・モスク", desc: "テルパク・フルションのドームの隣に建つ1637年の2階建てのモスクで、マゴキ・アッタリに次ぐブハラ二つ目の「沈んだ」モスクです。下の階は何世紀も積もった土にほぼ半分埋もれているので、階段を下りて入ります。「クルパ」は布団をつくっていた街区の名に由来します。上下階ともドームに覆われ、一部は鍾乳石状の天井で、主ドームは高さ約20mに達します。伝説では金曜モスクとして建てられるはずでしたが、小さすぎたため街区のモスクになったといいます。" },
    tr: { name: "Magok-i Kurpa Camii", desc: "Telpakfuruşan kubbesinin yanında 1637 tarihli iki katlı bir cami – Magok-i Attari'den sonra Buhara'nın ikinci “gömük” camii. Alt katı yüzyıllar boyunca biriken toprakla neredeyse yarı yarıya örtülmüştür, bu yüzden merdivenle inilerek girilir. “Kurpa” adı yorgan yapılan mahalleden gelir. İki kat da kubbelerle örtülüdür, bazıları mukarnaslıdır; ana kubbe yaklaşık yirmi metre yükselir. Rivayete göre Cuma camii olarak yapılacaktı ama küçük kalınca mahalle camii oldu." },
    ar: { name: "مسجد مغاكي كورپه", desc: "مسجد من طابقين يعود إلى عام 1637 بجوار قبة تلباك فوروشون – ثاني المساجد «الغائرة» في بخارى بعد مغاكي عطاري. طابقه السفلي مطمور إلى نصفه تقريبًا تحت التراب المتراكم عبر القرون، فيُنزل إليه بدرج. واسم «كورپه» مأخوذ من الحي الذي كانت تُصنع فيه اللُّحُف. الطابقان مسقوفان بقباب، بعضها بالمقرنصات، وترتفع القبة الرئيسية نحو عشرين مترًا. تقول الأسطورة إنه أُريد مسجدًا جامعًا لكنه ضاق، فصار مسجد حي." },
  },
  "bx-gaukushon": {
    zh: { name: "高库雄建筑群", desc: "老城南部16世纪的建筑群，由一座经学院、霍贾·卡隆清真寺和一座宣礼塔组成。它由朱伊巴尔赛义德家族中颇具影响力的谢赫霍贾·萨阿德修建。“高库雄”意为“宰牛者”，让人想起这里过去的屠宰场和肉类集市。带宽敞庭院的经学院已经修复，宿舍里开设了手工作坊，纤细的砖砌宣礼塔则是拍照时避开热闹的波伊·卡扬的安静选择。" },
    ko: { name: "가우쿠숀 단지", desc: "구시가지 남쪽에 있는 16세기 단지로, 마드라사와 호자 칼론 모스크, 미나렛으로 이루어져 있습니다. 주이바르 사이이드 가문의 유력한 셰이흐 호자 사아드가 세웠습니다. ‘가우쿠숀’은 ‘소 잡는 사람들’이라는 뜻으로, 예전에 이곳에 있던 도축장과 고기 시장을 떠올리게 합니다. 넓은 안뜰의 마드라사는 복원되어 방마다 공예 공방이 들어섰고, 날씬한 벽돌 미나렛은 붐비는 포이 칼론 대신 조용히 사진 찍기 좋은 곳입니다." },
    de: { name: "Ensemble Gaukuschon", desc: "Ein Ensemble aus dem 16. Jahrhundert mit Medrese, Chodscha-Kalon-Moschee und Minarett im Süden der Altstadt. Erbaut hat es der einflussreiche Scheich Chodscha Saad aus der Familie der Dschuibari-Sayyids. Der Name Gaukuschon, „Stiertöter“, erinnert an das Schlachthaus und den Fleischbasar, die hier früher standen. Die Medrese mit ihrem weiten Hof ist restauriert, Handwerkswerkstätten belegen die Zellen, und das schlanke Ziegelminarett ist eine ruhige Fotoalternative zum belebten Poi-Kalon." },
    fr: { name: "Ensemble Gaoukouchon", desc: "Un ensemble du XVIe siècle réunissant une médersa, la mosquée Khodja Kalon et un minaret au sud de la vieille ville. Il fut bâti par l'influent cheikh Khodja Saad, des sayyids Djouïbari. Le nom Gaoukouchon, « tueurs de taureaux », rappelle l'abattoir et le bazar à viande qui s'y trouvaient. La médersa à la vaste cour a été restaurée et des ateliers d'artisans occupent ses cellules, tandis que le fin minaret de brique offre une alternative paisible au Poï-Kalian bondé pour les photos." },
    ja: { name: "ガウクション建築群", desc: "旧市街南部にある16世紀の建築群で、メドレセ、ホジャ・カロン・モスク、ミナレットからなります。ジュイバール・サイイド家の有力なシェイフ、ホジャ・サアドが建てました。「ガウクション」は「牛を屠る者たち」を意味し、かつてここにあった屠畜場と肉市場の名残です。広い中庭のメドレセは修復され、学生房には工芸の工房が入り、細いれんがのミナレットはにぎやかなポイ・カランに代わる静かな撮影スポットです。" },
    tr: { name: "Gavkuşan Külliyesi", desc: "Eski şehrin güneyinde bir medrese, Hoca Kalan Camii ve bir minareden oluşan 16. yüzyıl külliyesi. Cuybari seyyidlerinden nüfuzlu Şeyh Hoca Saad tarafından yaptırıldı. “Boğa kesenler” anlamına gelen Gavkuşan adı, önceden burada bulunan mezbaha ve et pazarını hatırlatır. Geniş avlulu medrese restore edildi, hücrelerinde zanaat atölyeleri var; ince tuğla minare ise kalabalık Poyi Kalan'a karşı fotoğraf için sakin bir alternatif." },
    ar: { name: "مجمع غاوكوشون", desc: "مجمع من القرن السادس عشر جنوب المدينة القديمة يضم مدرسة ومسجد خواجه كلان ومئذنة. بناه الشيخ النافذ خواجه سعد من سادة الجويباري. ويذكّر اسم «غاوكوشون» أي «ذابحو الثيران» بالمسلخ وسوق اللحم اللذين كانا هنا. رُمّمت المدرسة ذات الفناء الواسع، وتشغل ورش الحرفيين حجراتها، أما المئذنة الآجرية الرشيقة فبديل هادئ للتصوير بعيدًا عن زحام بوي كلان." },
  },
  "bx-namazgoh": {
    zh: { name: "纳马兹戈清真寺", desc: "布哈拉西南部的一座露天节日清真寺，古尔邦节和开斋节时成千上万的人聚集在此礼拜。喀喇汗王朝时期这里就有节日礼拜场，现存带米哈拉布的朝向墙建于1119–1120年穆罕默德·阿尔斯兰汗时期。米哈拉布饰有雕刻赤陶和釉面，16世纪又增建了廊台。它远离旅游路线，十分安静——可乘出租车或从萨曼公园步行前往。" },
    ko: { name: "나마즈고흐 모스크", desc: "부하라 남서쪽에 있는 노천 명절 모스크로, 쿠르반 바이람과 라마단 바이람 때 수천 명이 예배하러 모였습니다. 카라한 왕조 때부터 명절 예배터가 있었고, 지금의 미흐랍이 있는 키블라 벽은 1119~1120년 무함마드 아르슬란 칸 시대에 세워졌습니다. 미흐랍은 조각 테라코타와 유약으로 장식되었고, 16세기에 아이반이 더해졌습니다. 관광 동선에서 벗어나 조용하니 택시를 타거나 사만 공원에서 걸어가세요." },
    de: { name: "Namazgoh-Moschee", desc: "Eine Festmoschee unter freiem Himmel im Südwesten Bucharas, wo sich Tausende zum Gebet an Opferfest und Fastenbrechen versammelten. Ein Festgebetsplatz bestand hier schon unter den Karachaniden; die heutige Qibla-Wand mit Mihrab entstand 1119–1120 unter Muhammad Arslan Khan. Der Mihrab ist mit geschnitzter Terrakotta und Glasur geschmückt, im 16. Jahrhundert kamen Aiwane hinzu. Sie liegt abseits der Touristenrouten und ist ruhig – nehmen Sie ein Taxi oder gehen Sie vom Samaniden-Park." },
    fr: { name: "Mosquée Namazgoh", desc: "Une mosquée de fête en plein air au sud-ouest de Boukhara, où des milliers de fidèles se réunissaient pour les prières de l'Aïd al-Adha et de l'Aïd al-Fitr. Un lieu de prière festive existait déjà sous les Karakhanides, et l'actuel mur de qibla avec son mihrab fut bâti en 1119–1120 sous Mouhammad Arslan Khan. Le mihrab est orné de terre cuite sculptée et de glaçure, et des aïvans furent ajoutés au XVIe siècle. Hors des circuits touristiques, c'est un lieu calme – prenez un taxi ou venez à pied du parc Samanide." },
    ja: { name: "ナマズゴフ・モスク", desc: "ブハラ南西部にある野外の祭礼用モスクで、犠牲祭や断食明けの祭りには何千人もの人々が礼拝に集まりました。カラハン朝の時代からここに祭礼の礼拝場があり、現在のミフラーブのあるキブラ壁は1119～1120年にムハンマド・アルスラン・ハンのもとで建てられました。ミフラーブは彫刻テラコッタと釉薬で飾られ、16世紀にはアイヴァンが加えられました。観光ルートから外れていて静かです。タクシーか、サーマーン公園から歩いて訪れましょう。" },
    tr: { name: "Namazgah Camii", desc: "Buhara'nın güneybatısında, binlerce kişinin Kurban ve Ramazan bayramı namazları için toplandığı açık hava bayram camii. Burada Karahanlılar döneminde de bir bayram namazgâhı vardı; mihraplı bugünkü kıble duvarı 1119–1120'de Muhammed Arslan Han döneminde yapıldı. Mihrap oymalı pişmiş toprak ve sırla süslenmiştir; 16. yüzyılda eyvanlar eklendi. Turist rotalarının dışında olduğu için sakindir – taksiyle gidin ya da Samani Parkı'ndan yürüyün." },
    ar: { name: "مسجد نمازگاه", desc: "مسجد أعياد في الهواء الطلق جنوب غرب بخارى، كان آلاف الناس يجتمعون فيه لصلاة عيدي الأضحى والفطر. وُجد هنا مصلى للأعياد منذ عهد القراخانيين، أما جدار القبلة الحالي بمحرابه فبُني بين 1119 و1120 في عهد محمد أرسلان خان. المحراب مزدان بالطين المحروق المنحوت والطلاء المزجج، وأُضيفت الأواوين في القرن السادس عشر. يقع بعيدًا عن مسارات السياح فهو هادئ – خذ سيارة أجرة أو امشِ من حديقة السامانيين." },
  },
  "bx-finearts": {
    zh: { name: "美术博物馆", desc: "布哈拉博物馆保护区下属的美术馆，位于老城中心一座20世纪初的历史建筑内。藏品涵盖与布哈拉有关的绘画、版画和雕塑，从描绘这座城市及其居民的俄罗斯和欧洲画家，到20世纪乌兹别克大师的作品。这里是透过艺术家的眼睛看布哈拉、在参观经学院间隙避暑的好去处。展厅紧凑，一个小时足够。" },
    ko: { name: "미술 박물관", desc: "부하라 박물관 보호구역의 미술관으로, 구시가지 중심의 20세기 초 역사 건물에 있습니다. 도시와 사람들을 그린 러시아·유럽 화가들부터 20세기 우즈베크 거장들까지, 부하라와 관련된 회화, 판화, 조각을 소장하고 있습니다. 예술가의 눈으로 부하라를 보고, 마드라사 사이사이 더위를 피해 쉬어 가기 좋습니다. 전시실이 아담해 한 시간이면 충분합니다." },
    de: { name: "Museum der Schönen Künste", desc: "Das Kunstmuseum des Museumsreservats Buchara in einem historischen Gebäude aus dem frühen 20. Jahrhundert im Zentrum der Altstadt. Die Sammlung umfasst Malerei, Grafik und Skulptur mit Bezug zu Buchara – von russischen und europäischen Künstlern, die Stadt und Menschen malten, bis zu Werken usbekischer Meister des 20. Jahrhunderts. Ein guter Ort, um Buchara mit Künstleraugen zu sehen und zwischen den Medresen der Hitze zu entfliehen. Die Räume sind kompakt; eine Stunde reicht." },
    fr: { name: "Musée des Beaux-Arts", desc: "Le musée d'art de la réserve-musée de Boukhara, installé dans un bâtiment historique du début du XXe siècle au centre de la vieille ville. La collection réunit peinture, arts graphiques et sculpture liés à Boukhara, des artistes russes et européens qui peignirent la ville et ses habitants aux maîtres ouzbeks du XXe siècle. Un bon endroit pour voir Boukhara par les yeux des artistes et fuir la chaleur entre deux médersas. Les salles sont compactes ; une heure suffit." },
    ja: { name: "美術博物館", desc: "ブハラ博物館保護区の美術館で、旧市街の中心にある20世紀初めの歴史的建物に入っています。町と人々を描いたロシアやヨーロッパの画家から20世紀のウズベクの巨匠まで、ブハラにまつわる絵画、版画、彫刻を所蔵しています。芸術家の目でブハラを見ながら、メドレセめぐりの合間に暑さを避けて休むのにぴったりです。展示室はこぢんまりしていて、1時間あれば十分です。" },
    tr: { name: "Güzel Sanatlar Müzesi", desc: "Buhara Müze-Koruma Alanı'nın sanat müzesi; eski şehrin merkezinde 20. yüzyıl başından kalma tarihi bir binada. Koleksiyon, şehri ve halkını resmeden Rus ve Avrupalı sanatçılardan 20. yüzyıl Özbek ustalarına kadar Buhara ile ilgili resim, grafik ve heykeli kapsar. Buhara'yı sanatçıların gözünden görmek ve medreseler arasında sıcaktan kaçmak için iyi bir yer. Salonlar küçüktür; bir saat yeterlidir." },
    ar: { name: "متحف الفنون الجميلة", desc: "المتحف الفني لمحمية بخارى المتحفية، في مبنى تاريخي من مطلع القرن العشرين وسط المدينة القديمة. تضم المجموعة لوحات ورسومات ومنحوتات مرتبطة ببخارى، من فنانين روس وأوروبيين رسموا المدينة وأهلها إلى أعمال أساتذة أوزبك من القرن العشرين. مكان جيد لرؤية بخارى بعيون الفنانين والاحتماء من الحر بين المدارس. القاعات صغيرة، وتكفي ساعة." },
  },
  "bx-khodjaev": {
    zh: { name: "法伊祖拉·霍贾耶夫故居博物馆", desc: "一座19世纪末布哈拉富商的宅邸，法伊祖拉·霍贾耶夫在此长大——他曾任布哈拉人民苏维埃共和国领导人，后任乌兹别克苏维埃社会主义共和国政府首脑，1938年被处决。宅院分为男女两部分，各有独立庭院；雕花天花板、彩绘石膏墙、摆满器皿的壁龛以及带馕坑和大锅的老厨房都保存了下来。2023年修复后，博物馆展出500多件关于商人家庭生活和布哈拉贸易的展品。" },
    ko: { name: "파이줄라 호자예프 생가 박물관", desc: "19세기 말 부하라 부유한 상인의 저택으로, 부하라 인민 소비에트 공화국의 지도자이자 훗날 우즈베크 SSR 정부 수반이었다가 1938년 처형된 파이줄라 호자예프가 자란 곳입니다. 집은 남성 구역과 여성 구역으로 나뉘어 각기 안뜰이 있고, 조각 천장, 채색 간치 벽, 그릇이 가득한 벽감, 탄두르와 가마솥이 있는 옛 부엌이 남아 있습니다. 2023년 복원 후 상인 가족의 생활과 부하라 교역에 관한 500점 넘는 유물을 전시합니다." },
    de: { name: "Fayzulla-Chodschajew-Hausmuseum", desc: "Das Haus eines reichen Bucharaer Kaufmanns aus dem späten 19. Jahrhundert, in dem Fayzulla Chodschajew aufwuchs – Oberhaupt der Buchara-Volkssowjetrepublik und später der Regierung der Usbekischen SSR, 1938 hingerichtet. Das Haus ist in Männer- und Frauentrakt mit eigenen Höfen geteilt; geschnitzte Decken, bemalte Gantschwände, Nischen voller Geschirr und eine alte Küche mit Tandyr und Kesseln sind erhalten. Nach der Restaurierung 2023 zeigt das Museum über 500 Objekte zum Leben einer Kaufmannsfamilie und zum Handel Bucharas." },
    fr: { name: "Maison-musée de Faïzoulla Khodjaïev", desc: "La demeure d'un riche marchand de Boukhara de la fin du XIXe siècle, où grandit Faïzoulla Khodjaïev – dirigeant de la République populaire soviétique de Boukhara puis du gouvernement de la RSS d'Ouzbékistan, exécuté en 1938. La maison est divisée en quartiers des hommes et des femmes avec leurs propres cours ; plafonds sculptés, murs de ganch peints, niches remplies de vaisselle et vieille cuisine avec tandour et chaudrons ont survécu. Restaurée en 2023, elle présente plus de 500 objets sur la vie d'une famille marchande et le commerce de Boukhara." },
    ja: { name: "ファイズッラ・ホジャエフ記念館", desc: "19世紀末のブハラの豪商の屋敷で、ブハラ人民ソビエト共和国の指導者、のちにウズベク・ソビエト社会主義共和国政府の長となり1938年に処刑されたファイズッラ・ホジャエフが育った家です。家は男性用と女性用の区画に分かれ、それぞれに中庭があります。彫刻の天井、彩色のガンチ壁、器を並べた壁龕、タンディルと大鍋のある古い台所が残っています。2023年の修復後、商家の暮らしとブハラの交易に関する500点以上の品を展示しています。" },
    tr: { name: "Fayzulla Hocayev Ev Müzesi", desc: "19. yüzyıl sonundan zengin bir Buharalı tüccarın evi; Buhara Halk Sovyet Cumhuriyeti'nin başkanı, sonra Özbek SSC hükümetinin başı olan ve 1938'de kurşuna dizilen Fayzulla Hocayev burada büyüdü. Ev, ayrı avlulara sahip erkek ve kadın bölümlerine ayrılmıştır; oymalı tavanlar, boyalı alçı duvarlar, kap kacakla dolu nişler ve tandırlı, kazanlı eski bir mutfak korunmuştur. 2023'teki restorasyondan sonra müze tüccar ailesinin yaşamına ve Buhara ticaretine dair 500'den fazla eser sergiliyor." },
    ar: { name: "بيت متحف فيض الله خوجاييف", desc: "منزل تاجر بخاري ثري من أواخر القرن التاسع عشر، نشأ فيه فيض الله خوجاييف – رئيس جمهورية بخارى السوفيتية الشعبية ثم رئيس حكومة جمهورية أوزبكستان السوفيتية، الذي أُعدم عام 1938. ينقسم البيت إلى جناحين للرجال والنساء لكل منهما فناؤه، وقد بقيت الأسقف المنحوتة وجدران الجص المرسومة والكوى المليئة بالأواني ومطبخ قديم بتنور وقدور. وبعد ترميمه عام 2023 يعرض المتحف أكثر من 500 قطعة عن حياة أسرة تاجر وتجارة بخارى." },
  },
  "bx-sitorai": {
    zh: { name: "西托莱·莫希·霍萨宫", desc: "布哈拉末代埃米尔们的郊外行宫，位于城北几公里处——“如星似月的宫殿”。19世纪较早的建筑已不复存在；现存建筑群主要建于20世纪10年代埃米尔阿利姆汗时期。外立面是欧式风格，内部则是东方的华丽：著名的白厅中，大师希林·穆拉多夫在镜面底上制作了雕花石膏装饰。如今这里是实用艺术博物馆，孔雀在后宫水池边的花园里漫步。" },
    ko: { name: "시토라이 모히 호사 궁전", desc: "도시 북쪽 몇 km에 있는 부하라 마지막 에미르들의 별궁, ‘별과 달 같은 궁전’입니다. 19세기의 옛 건물은 남아 있지 않고, 지금의 건물들은 주로 1910년대 에미르 알림 칸 시대에 지어졌습니다. 밖은 유럽식 파사드, 안은 동양의 화려함으로, 장인 시린 무라도프가 거울 바탕 위에 간치 조각을 새긴 유명한 ‘하얀 홀’이 있습니다. 지금은 응용미술 박물관이며, 하렘 연못가 정원에서는 공작이 거닙니다." },
    de: { name: "Palast Sitorai Mochi-Chosa", desc: "Die Landresidenz der letzten Emire von Buchara, einige Kilometer nördlich der Stadt – der „Palast gleich Sternen und Mond“. Die älteren Bauten des 19. Jahrhunderts sind verschwunden; der heutige Komplex entstand hauptsächlich unter Emir Alim Khan in den 1910er-Jahren. Außen europäische Fassaden, innen orientalische Pracht: der berühmte Weiße Saal mit geschnitztem Gantsch auf Spiegelgrund von Meister Schirin Muradow. Heute ist er ein Museum für angewandte Kunst, und im Garten am Haremsteich spazieren Pfauen." },
    fr: { name: "Palais de Sitoraï Mokhi-Khossa", desc: "La résidence de campagne des derniers émirs de Boukhara, à quelques kilomètres au nord de la ville – le « palais semblable aux étoiles et à la lune ». Les bâtiments plus anciens du XIXe siècle ont disparu ; l'ensemble actuel fut construit surtout sous l'émir Alim Khan dans les années 1910. À l'extérieur, des façades européennes ; à l'intérieur, la splendeur orientale : la célèbre Salle blanche au ganch sculpté sur fond de miroirs, œuvre du maître Chirin Mouradov. C'est aujourd'hui un musée des arts appliqués, et des paons se promènent dans le jardin près du bassin du harem." },
    ja: { name: "シトライ・マヒ・ホサ宮殿", desc: "町の北数kmにあるブハラ最後のアミールたちの離宮で、「星と月のような宮殿」を意味します。19世紀の古い建物は残っておらず、現在の建物群は主に1910年代にアミール・アリム・ハンのもとで建てられました。外観はヨーロッパ風のファサード、内部は東洋の豪華さで、名工シリン・ムラドフが鏡の地にガンチ彫刻を施した有名な「白の間」があります。現在は応用美術博物館で、ハーレムの池のそばの庭をクジャクが歩いています。" },
    tr: { name: "Sitorai Mohi Hasa Sarayı", desc: "Buhara'nın son emirlerinin, şehrin birkaç kilometre kuzeyindeki sayfiye sarayı – “Yıldızlar ve Ay Gibi Saray”. 19. yüzyılın eski yapıları yok olmuştur; bugünkü kompleks büyük ölçüde 1910'larda Emir Alim Han döneminde yapıldı. Dışta Avrupai cepheler, içte Doğu ihtişamı: usta Şirin Muradov'un ayna zemin üzerine oymalı alçı işlediği ünlü Beyaz Salon. Bugün uygulamalı sanatlar müzesidir; harem havuzunun yanındaki bahçede tavuskuşları dolaşır." },
    ar: { name: "قصر ستوراي ماهي خاصه", desc: "المقر الريفي لآخر أمراء بخارى، على بعد بضعة كيلومترات شمال المدينة – «القصر الشبيه بالنجوم والقمر». زالت المباني الأقدم من القرن التاسع عشر، وبُني المجمع الحالي أساسًا في عهد الأمير عالم خان في العقد الثاني من القرن العشرين. واجهات أوروبية من الخارج، وفخامة شرقية في الداخل: القاعة البيضاء الشهيرة بجصها المنحوت على أرضية من المرايا من صنع الأستاذ شيرين مرادوف. وهو اليوم متحف للفنون التطبيقية، والطواويس تتجول في الحديقة قرب حوض الحريم." },
  },
  "bx-fayzobod": {
    zh: { name: "法伊扎巴德修道院", desc: "老城以东原法伊扎巴德郊区的一座16世纪末苏菲修道院，由托钵僧毛拉诺·波扬达·穆罕默德·阿赫西修建。苏菲聚会用的大厅覆盖着帆拱上的穹顶，两侧是为朝圣者和弟子准备的单层宿舍回廊。修道院远离主要路线，几乎没有游客——如果想看看没有人群的布哈拉，值得绕道一游。" },
    ko: { name: "파이자바드 하나카", desc: "구시가지 동쪽, 옛 교외 파이자바드에 있는 16세기 말 수피 수도원으로, 수도사 마블로노 포얀다 무함마드 악시가 세웠습니다. 수피 집회용 큰 홀은 펜던티브 위의 돔으로 덮였고, 양옆으로 순례자와 제자를 위한 단층 방 회랑이 이어집니다. 주요 동선에서 벗어나 관광객이 거의 없으니, 인파 없는 부하라를 보고 싶다면 들러 볼 만합니다." },
    de: { name: "Chanaka Fayzabad", desc: "Eine Sufi-Herberge aus dem späten 16. Jahrhundert im einstigen Vorort Fayzabad östlich der Altstadt, erbaut vom Derwisch Mavlono Poyanda-Muhammad Achsi. Der große Saal für Sufi-Zusammenkünfte trägt eine Kuppel auf Pendentifs, an den Seiten laufen einstöckige Zellengalerien für Pilger und Schüler. Die Chanaka liegt abseits der Hauptrouten, Touristen gibt es kaum – ein lohnender Abstecher für ein Buchara ohne Menschenmassen." },
    fr: { name: "Khanqah de Faïzabad", desc: "Une demeure soufie de la fin du XVIe siècle dans l'ancien faubourg de Faïzabad, à l'est de la vieille ville, bâtie par le derviche Mavlono Poïanda-Mouhammad Akhsi. La grande salle des réunions soufies est couverte d'une coupole sur pendentifs, et des galeries de cellules à un niveau pour pèlerins et disciples la longent. À l'écart des grands circuits, elle n'attire presque aucun touriste – le détour vaut la peine pour voir Boukhara sans la foule." },
    ja: { name: "ファイザバード・ハナカ", desc: "旧市街の東、かつての郊外ファイザバードにある16世紀末のスーフィーの修道場で、托鉢僧マヴロノ・ポヤンダ・ムハンマド・アフシーが建てました。スーフィーの集いのための大広間はペンデンティブの上のドームに覆われ、両側には巡礼者や弟子のための平屋の房の回廊が続きます。主要ルートから外れていて観光客はほとんどいません。人混みのないブハラを見たいなら寄り道する価値があります。" },
    tr: { name: "Feyzabad Hankahı", desc: "Eski şehrin doğusunda, eski Feyzabad banliyösünde 16. yüzyıl sonundan bir sufi tekkesi; derviş Mevlana Poyende Muhammed Ahsi tarafından yaptırıldı. Sufi toplantıları için büyük salon pandantifler üzerinde bir kubbeyle örtülüdür; yanlarında hacılar ve müritler için tek katlı hücre galerileri uzanır. Ana rotaların dışında olduğu için neredeyse hiç turist yoktur – kalabalıksız bir Buhara görmek istiyorsanız uğramaya değer." },
    ar: { name: "خانقاه فيض آباد", desc: "خانقاه صوفية من أواخر القرن السادس عشر في ضاحية فيض آباد السابقة شرق المدينة القديمة، بناها الدرويش مولانا بويندة محمد الأخسي. تعلو قاعةَ الاجتماعات الصوفية الكبيرة قبةٌ على مثلثات كروية، وتمتد على جانبيها أروقة من طابق واحد لحجرات الزوار والمريدين. تقع بعيدًا عن المسارات الرئيسية فلا يكاد يزورها سياح – تستحق الالتفاف إن أردت رؤية بخارى بلا زحام." },
  },
  "bx-naqshband": {
    zh: { name: "巴哈丁·纳克什班德建筑群", desc: "布哈拉最神圣的地方，也是伊斯兰世界最受尊崇的朝圣地之一：纳克什班迪苏菲教团创始人巴哈丁·纳克什班德（1318–1389）的纪念建筑群，位于城东北约12公里的卡斯里·奥里丰村。建筑群包括圣人墓、16世纪阿卜杜拉齐兹汗修道院、带雕花廊台的清真寺、大水池、宣礼塔和墓地。朝圣者绕墓而行，并在一棵古树下许愿。请穿着得体；女士应包头巾。" },
    ko: { name: "바하우딘 낙시반드 단지", desc: "부하라에서 가장 성스러운 곳이자 이슬람 세계에서 가장 존경받는 순례지 중 하나로, 도시 북동쪽 약 12km 카스리 오리폰 마을에 있는 낙시반디 수피 교단 창시자 바하우딘 낙시반드(1318~1389)의 기념 단지입니다. 성인의 묘, 16세기 압둘아지즈 칸 하나카, 조각된 아이반의 모스크들, 큰 연못, 미나렛, 묘지가 있습니다. 순례자들은 묘를 돌고 오래된 나무 아래에서 소원을 빕니다. 단정하게 입고, 여성은 머리를 가리세요." },
    de: { name: "Bahauddin-Naqschband-Komplex", desc: "Bucharas heiligster Ort und eine der meistverehrten Pilgerstätten der islamischen Welt: die Gedenkstätte von Bahauddin Naqschband (1318–1389), Gründer des Naqschbandi-Sufiordens, im Dorf Kasri Orifon etwa 12 km nordöstlich der Stadt. Zum Komplex gehören das Grab des Heiligen, die Chanaka Abdulaziz Khans aus dem 16. Jahrhundert, Moscheen mit geschnitzten Aiwanen, ein großer Teich, ein Minarett und eine Nekropole. Pilger umrunden das Grab und wünschen sich etwas an einem alten Baum. Zurückhaltend kleiden; Frauen bedecken das Haar." },
    fr: { name: "Complexe de Bahaouddin Naqchband", desc: "Le lieu le plus saint de Boukhara et l'un des pèlerinages les plus vénérés du monde islamique : le mémorial de Bahaouddin Naqchband (1318–1389), fondateur de l'ordre soufi Naqchbandi, au village de Kasri Orifon, à environ 12 km au nord-est de la ville. Le complexe comprend la tombe du saint, la khanqah d'Abdoulaziz Khan du XVIe siècle, des mosquées aux aïvans sculptés, un grand bassin, un minaret et une nécropole. Les pèlerins font le tour de la tombe et formulent des vœux près d'un vieil arbre. Tenue correcte ; les femmes se couvrent les cheveux." },
    ja: { name: "バハウッディーン・ナクシュバンド廟建築群", desc: "ブハラで最も神聖な場所で、イスラム世界で最も崇敬される巡礼地の一つです。町の北東約12kmのカスリ・オリフォン村にある、ナクシュバンディー教団の創始者バハウッディーン・ナクシュバンド（1318～1389）の記念建築群で、聖者の墓、16世紀のアブドゥルアジズ・ハンのハナカ、彫刻のアイヴァンをもつモスク、大きな池、ミナレット、墓地があります。巡礼者は墓の周りを巡り、古木のそばで願い事をします。控えめな服装で、女性は髪を覆ってください。" },
    tr: { name: "Bahaeddin Nakşibend Külliyesi", desc: "Buhara'nın en kutsal yeri ve İslam dünyasının en saygın ziyaretgâhlarından biri: Nakşibendi tarikatının kurucusu Bahaeddin Nakşibend'in (1318–1389) anıt külliyesi, şehrin yaklaşık 12 km kuzeydoğusundaki Kasr-ı Arifan köyünde. Külliyede velinin kabri, 16. yüzyıldan Abdülaziz Han hankahı, oymalı eyvanlı camiler, büyük bir havuz, bir minare ve bir mezarlık bulunur. Ziyaretçiler kabri tavaf eder ve yaşlı bir ağacın yanında dilek tutar. Kapalı giyinin; kadınlar başını örtmeli." },
    ar: { name: "مجمع بهاء الدين نقشبند", desc: "أقدس أماكن بخارى ومن أكثر أماكن الزيارة تبجيلًا في العالم الإسلامي: الضريح التذكاري لبهاء الدين نقشبند (1318–1389)، مؤسس الطريقة النقشبندية، في قرية قصر عارفان على بعد نحو 12 كم شمال شرق المدينة. يضم المجمع قبر الولي، وخانقاه عبد العزيز خان من القرن السادس عشر، ومساجد بأواوين منحوتة، وحوضًا كبيرًا، ومئذنة، ومقبرة. يطوف الزوار حول القبر ويتمنّون الأماني عند شجرة معمّرة. ارتدِ ملابس محتشمة، وعلى النساء تغطية الشعر." },
  },
  "bx-chorbakr": {
    zh: { name: "乔尔·巴克尔墓地", desc: "布哈拉以西约5公里苏米坦村的纪念建筑群，因一条条家族墓葬小巷而被称为“死者之城”。它围绕10世纪去世的阿布·伯克尔·萨阿德之墓发展而来——他是使此地得名的四位阿布·伯克尔之一。清真寺、修道院和经学院组成的建筑群由阿卜杜拉汗二世于1559–1563年为王朝强大的庇护者朱伊巴尔谢赫们修建。高大的门楼、安静的庭院和玫瑰园，使它成为绿洲中最有氛围的地方之一。" },
    ko: { name: "초르 바크르 묘역", desc: "부하라 서쪽 약 5km 수미탄 마을에 있는 기념 단지로, 가족 묘가 늘어선 골목 때문에 ‘죽은 자들의 도시’라는 별명이 있습니다. 이곳 이름의 유래가 된 네 명의 아부 바크르 중 하나로 10세기에 세상을 떠난 아부 바크르 사아드의 묘를 중심으로 형성되었습니다. 모스크, 하나카, 마드라사로 이루어진 단지는 1559~1563년 압둘라 칸 2세가 왕조의 강력한 후원자였던 주이바르 셰이흐들을 위해 세웠습니다. 높은 정문, 고요한 안뜰, 장미 정원이 오아시스에서 가장 분위기 있는 곳으로 만들어 줍니다." },
    de: { name: "Nekropole Tschor-Bakr", desc: "Ein Gedenkkomplex im Dorf Sumitan etwa 5 km westlich von Buchara, wegen seiner Gassen aus Familiengräbern „Stadt der Toten“ genannt. Er wuchs um das Grab von Abu Bakr Saad, gestorben im 10. Jahrhundert – einer der vier Abu Bakrs, die dem Ort den Namen gaben. Das Ensemble aus Moschee, Chanaka und Medrese erbaute Abdullah Khan II. 1559–1563 für die Dschuibari-Scheichs, mächtige Förderer der Dynastie. Hohe Portale, stille Höfe und Rosengärten machen ihn zu einem der stimmungsvollsten Orte der Oase." },
    fr: { name: "Nécropole de Tchor-Bakr", desc: "Un complexe mémorial au village de Soumitan, à environ 5 km à l'ouest de Boukhara, surnommé la « Cité des morts » pour ses ruelles de tombeaux familiaux. Il s'est développé autour de la tombe d'Abou Bakr Saad, mort au Xe siècle – l'un des quatre Abou Bakr qui ont donné son nom au lieu. L'ensemble mosquée, khanqah et médersa fut bâti en 1559–1563 par Abdoullah Khan II pour les cheikhs Djouïbari, puissants protecteurs de la dynastie. Hauts portails, cours paisibles et roseraies en font l'un des lieux les plus envoûtants de l'oasis." },
    ja: { name: "チョル・バクル墓廟群", desc: "ブハラの西約5kmのスミタン村にある記念建築群で、一族の墓が並ぶ路地から「死者の町」とも呼ばれます。この地の名の由来となった4人のアブー・バクルの一人で、10世紀に亡くなったアブー・バクル・サアドの墓を中心に形成されました。モスク、ハナカ、メドレセからなる建築群は、1559～1563年にアブドゥッラー・ハン2世が王朝の有力な後ろ盾ジュイバールのシェイフたちのために建てたものです。高い門、静かな中庭、バラ園が、オアシスで最も趣のある場所の一つにしています。" },
    tr: { name: "Çor Bakr Nekropolü", desc: "Buhara'nın yaklaşık 5 km batısında Sumitan köyünde, aile türbelerinden oluşan sokakları nedeniyle “Ölüler Şehri” denen anıt külliye. Yere adını veren dört Ebubekir'den biri olan, 10. yüzyılda ölen Ebubekir Saad'ın mezarı etrafında gelişti. Cami, hankah ve medreseden oluşan külliyeyi II. Abdullah Han 1559–1563'te hanedanın güçlü hamileri Cuybari şeyhleri için yaptırdı. Yüksek taç kapılar, sakin avlular ve gül bahçeleri onu vahanın en atmosferik yerlerinden biri yapar." },
    ar: { name: "مقبرة تشور بكر", desc: "مجمع تذكاري في قرية سوميتان على بعد نحو 5 كم غرب بخارى، يُلقَّب بـ«مدينة الموتى» لأزقته المكوّنة من أضرحة عائلية. نشأ حول قبر أبي بكر سعد المتوفى في القرن العاشر – أحد «الأبي بكر» الأربعة الذين أعطوا المكان اسمه. بنى عبد الله خان الثاني مجمع المسجد والخانقاه والمدرسة بين 1559 و1563 لشيوخ الجويباري، الرعاة الأقوياء للأسرة الحاكمة. البوابات العالية والأفنية الهادئة وحدائق الورد تجعله من أكثر أماكن الواحة سحرًا." },
  },
  "bx-gijduvani": {
    zh: { name: "阿卜杜哈利克·吉日杜瓦尼纪念建筑群", desc: "位于布哈拉东北约45公里吉日杜万镇的纪念建筑群，在12世纪苏菲导师阿卜杜哈利克·吉日杜瓦尼墓旁——他是布哈拉“七圣”中的第一位，其教义奠定了纳克什班迪教团的基础。旁边是兀鲁伯1433年修建的经学院，是他三座经学院中最后也最简朴的一座。朝圣者通常从这里开始“七位导师”之路。吉日杜万还以世代相传的陶工制作的陶器闻名。" },
    ko: { name: "압둘할리크 기즈두바니 기념 단지", desc: "부하라 북동쪽 약 45km 기즈두반 시에 있는 기념 단지로, 부하라 ‘일곱 성인’ 중 첫째이자 그 가르침이 낙시반디 교단의 토대가 된 12세기 수피 스승 압둘할리크 기즈두바니의 묘 옆에 있습니다. 곁에는 울루그베크가 1433년 세운, 그의 세 마드라사 중 마지막이자 가장 소박한 마드라사가 있습니다. 순례자들은 보통 이곳에서 ‘일곱 피르’ 순례를 시작합니다. 기즈두반은 대대로 이어 온 도공들의 도자기로도 유명합니다." },
    de: { name: "Gedenkstätte Abdulchaliq Gijduvani", desc: "Ein Gedenkkomplex in der Stadt Gijduvon, etwa 45 km nordöstlich von Buchara, am Grab des Sufi-Meisters Abdulchaliq Gijduvani aus dem 12. Jahrhundert – des ersten der „sieben Heiligen“ Bucharas, dessen Lehre den Naqschbandi-Orden begründete. Daneben steht die von Ulugh Beg 1433 erbaute Medrese, die letzte und schlichteste seiner drei Medresen. Pilger beginnen hier meist die Route der „sieben Pire“. Gijduvon ist auch für seine Keramik berühmt, gefertigt von Töpferdynastien." },
    fr: { name: "Mémorial d'Abdoulkhaliq Guijdouvani", desc: "Un complexe mémorial dans la ville de Guijdouvan, à environ 45 km au nord-est de Boukhara, près de la tombe du maître soufi du XIIe siècle Abdoulkhaliq Guijdouvani – le premier des « sept saints » de Boukhara, dont l'enseignement fonda l'ordre Naqchbandi. À côté se dresse la médersa bâtie par Ouloug Beg en 1433, la dernière et la plus simple de ses trois médersas. Les pèlerins commencent généralement ici la route des « sept pirs ». Guijdouvan est aussi réputée pour sa céramique, œuvre de dynasties de potiers." },
    ja: { name: "アブドゥルハリク・ギジュドゥヴァーニー記念建築群", desc: "ブハラの北東約45kmのギジュドゥヴァンの町にある記念建築群で、12世紀のスーフィーの師アブドゥルハリク・ギジュドゥヴァーニーの墓のそばにあります。彼はブハラの「七聖人」の最初の一人で、その教えがナクシュバンディー教団の基礎となりました。隣には1433年にウルグベクが建てた、三つのメドレセのうち最後で最も簡素なメドレセが建っています。巡礼者はたいていここから「七人のピール」巡りを始めます。ギジュドゥヴァンは代々の陶工による陶器でも有名です。" },
    tr: { name: "Abdülhalık Gücdüvani Anıt Külliyesi", desc: "Buhara'nın yaklaşık 45 km kuzeydoğusundaki Gijduvan kasabasında, Buhara'nın “yedi velisi”nin ilki olan ve öğretisi Nakşibendiliğin temelini atan 12. yüzyıl sufi üstadı Abdülhalık Gücdüvani'nin kabri yanındaki anıt külliye. Yanında Uluğ Bey'in 1433'te yaptırdığı, üç medresesinin sonuncusu ve en sadesi olan medrese durur. Ziyaretçiler “yedi pir” yoluna genellikle buradan başlar. Gijduvan, kuşaktan kuşağa çömlekçilerin yaptığı seramikleriyle de ünlüdür." },
    ar: { name: "مجمع عبد الخالق الغجدواني التذكاري", desc: "مجمع تذكاري في بلدة غجدوان على بعد نحو 45 كم شمال شرق بخارى، عند قبر الشيخ الصوفي عبد الخالق الغجدواني من القرن الثاني عشر – أول «الأولياء السبعة» في بخارى، الذي وضعت تعاليمه أساس الطريقة النقشبندية. وبجانبه المدرسة التي بناها أولوغ بيك عام 1433، وهي آخر مدارسه الثلاث وأبسطها. يبدأ الزوار عادة من هنا مسار «البيرات السبعة». وتشتهر غجدوان كذلك بخزفها الذي تصنعه عائلات خزافين متوارثة." },
  },
  "bx-vobkent": {
    zh: { name: "瓦布肯特宣礼塔", desc: "瓦布肯特镇一座高约40米的砖砌宣礼塔，在布哈拉以北约30公里。它建于12世纪末（1196–1198年），为布哈拉宗教领袖萨德尔布尔汉丁·阿卜杜拉齐兹二世所建，他的名字被织入一条铭文带中。它就像卡扬宣礼塔的缩小版：花纹砖砌、库法体铭文带、蓝釉镶嵌，顶部是灯亭。去吉日杜万或绿洲北部圣地途中顺路参观很方便。" },
    ko: { name: "보브켄트 미나렛", desc: "부하라 북쪽 약 30km 보브켄트 시에 있는 높이 약 40m의 벽돌 미나렛입니다. 12세기 말(1196~1198) 부하라의 종교 지도자 사드르 부르하니딘 압둘아지즈 2세를 위해 세워졌으며, 그의 이름이 명문 띠에 새겨져 있습니다. 무늬 벽돌, 쿠픽체 명문 띠, 푸른 유약 장식, 꼭대기의 등탑을 갖춰 칼론 미나렛의 축소판처럼 보입니다. 기즈두반이나 오아시스 북쪽 성지로 가는 길에 들르기 좋습니다." },
    de: { name: "Minarett von Vobkent", desc: "Ein etwa 40 Meter hohes Ziegelminarett in der Stadt Vobkent, rund 30 km nördlich von Buchara. Es wurde Ende des 12. Jahrhunderts (1196–1198) für Burhaniddin Abdulaziz II., den Sadr von Buchara, errichtet, dessen Name in ein Inschriftband eingeflochten ist. Es wirkt wie eine kleinere Kopie des Kalon, mit gemustertem Mauerwerk, kufischen Inschriftbändern, blau glasierten Einlagen und einer Laternenrotunde oben. Gut auf dem Weg nach Gijduvon oder zu den Heiligtümern im Norden der Oase zu besuchen." },
    fr: { name: "Minaret de Vobkent", desc: "Un minaret de brique d'environ 40 mètres dans la ville de Vobkent, à quelque 30 km au nord de Boukhara. Il fut élevé à la fin du XIIe siècle (1196–1198) pour Bourhaniddin Abdoulaziz II, le sadr de Boukhara, dont le nom est tissé dans une bande d'inscription. Il ressemble à une copie réduite du Kalian : briques à motifs, bandes d'inscriptions coufiques, incrustations de glaçure bleue et lanterne au sommet. Facile à visiter en route vers Guijdouvan ou les sanctuaires du nord de l'oasis." },
    ja: { name: "ヴォブケント・ミナレット", desc: "ブハラの北約30kmのヴォブケントの町にある高さ約40mのれんがのミナレットです。12世紀末（1196～1198年）、ブハラのサドル（宗教指導者）ブルハニッディン・アブドゥルアジズ2世のために建てられ、その名が銘文帯に織り込まれています。模様れんが、クーフィー体の銘文帯、青い釉薬のはめ込み、頂上の灯籠部をもち、カラン・ミナレットの縮小版のようです。ギジュドゥヴァンやオアシス北部の聖地へ向かう途中に立ち寄りやすいです。" },
    tr: { name: "Vabkent Minaresi", desc: "Buhara'nın yaklaşık 30 km kuzeyindeki Vabkent kasabasında yaklaşık 40 metre yüksekliğinde tuğla minare. 12. yüzyıl sonunda (1196–1198) Buhara'nın sadrı Burhaneddin Abdülaziz II için yapıldı; adı bir yazı kuşağına işlenmiştir. Desenli tuğla örgüsü, Kufi yazı kuşakları, mavi sırlı kakmaları ve tepesindeki fener kısmıyla Kalan'ın küçültülmüş bir kopyasına benzer. Gijduvan'a ya da vahanın kuzeyindeki ziyaretgâhlara giderken uğramak kolaydır." },
    ar: { name: "مئذنة وابكنت", desc: "مئذنة من الآجر بارتفاع نحو 40 مترًا في بلدة وابكنت، على بعد قرابة 30 كم شمال بخارى. بُنيت في أواخر القرن الثاني عشر (1196–1198) لصدر بخارى برهان الدين عبد العزيز الثاني، المنسوج اسمه في شريط كتابي. تبدو كنسخة مصغرة من مئذنة كلان: آجر مزخرف، وأشرطة كتابات كوفية، وتطعيمات بالطلاء الأزرق، وفانوس في القمة. يسهل زيارتها في الطريق إلى غجدوان أو إلى المزارات في شمال الواحة." },
  },
  "bx-varakhsha": {
    zh: { name: "瓦拉赫沙古城遗址", desc: "布哈拉绿洲西缘一座古城的遗址，距布哈拉约40公里，正是沙漠的起点。这里曾是伊斯兰之前布哈拉统治者布哈拉胡达特的宫廷所在地，发掘出的宫殿出土了著名的7至8世纪壁画：国王和随从骑着大象与猛兽和怪物搏斗。11世纪运河不再引来水源，城市随之衰落。如今草原上只剩一座座土坯墙丘；没有像样的道路，请找认路的司机前往。" },
    ko: { name: "바라흐샤 고대 유적", desc: "사막이 시작되는 부하라 오아시스 서쪽 끝, 부하라에서 약 40km 떨어진 고대 도시의 유적입니다. 이슬람 이전 부하라의 통치자 부하르 후다트의 거처였으며, 발굴된 궁전에서 코끼리를 탄 왕과 신하들이 맹수와 괴물과 싸우는 유명한 7~8세기 벽화가 나왔습니다. 11세기 운하가 더 이상 물을 대지 못하자 도시는 쇠락했습니다. 지금은 초원 위 흙벽돌 벽의 언덕만 남아 있고 제대로 된 길이 없으니 길을 아는 기사와 함께 가세요." },
    de: { name: "Ruinenstätte Varachscha", desc: "Die Ruinen einer antiken Stadt am Westrand der Oase Buchara, etwa 40 km von Buchara, wo die Wüste beginnt. Hier residierten die Buchar-Chudat, die vorislamischen Herrscher Bucharas, und der ausgegrabene Palast lieferte berühmte Wandmalereien des 7.–8. Jahrhunderts: ein König und sein Gefolge auf Elefanten im Kampf mit Raubtieren und Ungeheuern. Im 11. Jahrhundert verfiel die Stadt, als die Kanäle kein Wasser mehr brachten. Heute sind es Hügel aus Lehmziegelmauern in der Steppe; eine richtige Straße gibt es nicht – fahren Sie mit einem ortskundigen Fahrer." },
    fr: { name: "Site antique de Varakhcha", desc: "Les ruines d'une cité antique à la lisière ouest de l'oasis de Boukhara, à environ 40 km de Boukhara, là où commence le désert. Ce fut la résidence des Boukhar Khoudat, souverains préislamiques de Boukhara, et le palais fouillé a livré de célèbres peintures murales des VIIe–VIIIe siècles : un roi et sa suite montés sur des éléphants combattant fauves et monstres. La ville déclina au XIe siècle quand les canaux cessèrent d'apporter l'eau. Il ne reste aujourd'hui que des buttes de murs en brique crue dans la steppe ; pas de vraie route, venez avec un chauffeur qui connaît le chemin." },
    ja: { name: "ヴァラフシャ遺跡", desc: "砂漠が始まるブハラ・オアシスの西端、ブハラから約40kmにある古代都市の遺跡です。イスラム以前のブハラの支配者ブハール・フダートの居所で、発掘された宮殿からは、象に乗った王と従者が猛獣や怪物と戦う有名な7～8世紀の壁画が見つかりました。11世紀に運河が水を運ばなくなると、町は衰退しました。今は草原に日干しれんがの壁の丘が残るだけで、まともな道はないので、道を知る運転手と行きましょう。" },
    tr: { name: "Varahşa Antik Kenti", desc: "Buhara vahasının batı ucunda, çölün başladığı yerde, Buhara'ya yaklaşık 40 km uzaklıkta antik bir kentin kalıntıları. Burası Buhara'nın İslam öncesi hükümdarları Buhar Hudatların ikametgâhıydı; kazılan saraydan, filler üzerinde vahşi hayvanlar ve canavarlarla savaşan bir kral ve maiyetini gösteren ünlü 7.–8. yüzyıl duvar resimleri çıktı. Kanallar su getirmez olunca kent 11. yüzyılda söndü. Bugün bozkırda kerpiç duvar tepeleri kalmıştır; düzgün yol yoktur, yolu bilen bir şoförle gidin." },
    ar: { name: "موقع ورخشة الأثري", desc: "أطلال مدينة قديمة على الطرف الغربي لواحة بخارى، على بعد نحو 40 كم من بخارى حيث تبدأ الصحراء. كانت مقر «بخار خداة» حكام بخارى قبل الإسلام، وكشف القصر المنقّب عنه عن جداريات شهيرة من القرنين السابع والثامن: ملك وحاشيته على الفيلة يقاتلون الوحوش والمخلوقات العجيبة. اضمحلت المدينة في القرن الحادي عشر حين توقفت القنوات عن جلب الماء. واليوم لا يبقى إلا تلال من جدران اللبن في السهوب؛ لا طريق ممهدًا، فاذهب مع سائق يعرف الطريق." },
  },
  "bx-paykend": {
    zh: { name: "古城派肯德", desc: "布哈拉绿洲最大城市之一的遗址，在布哈拉西南约40公里。派肯德被称为“商人之城”：它位于商路上，没有自己的统治者也能运转。706年阿拉伯将领屈底波·伊本·穆斯林围攻并攻占了它，到11世纪这里的生活已经衰落。自1981年起，冬宫博物馆和乌兹别克斯坦的考古学家发掘出要塞、城墙、街道和该地区最古老的清真寺之一。附近有一座出土文物博物馆。" },
    ko: { name: "고대 파이켄드", desc: "부하라 남서쪽 약 40km에 있는 부하라 오아시스 최대 도시 중 하나의 유적입니다. 파이켄드는 대상로에 자리해 자체 통치자 없이도 운영된 ‘상인들의 도시’로 불렸습니다. 706년 아랍 장군 쿠타이바 이븐 무슬림이 포위해 점령했고, 11세기에 이르러 삶이 쇠했습니다. 1981년부터 에르미타주와 우즈베키스탄 고고학자들이 성채, 성벽, 거리, 이 지역에서 가장 오래된 모스크 중 하나를 발굴했습니다. 근처에 출토품 박물관이 있습니다." },
    de: { name: "Antikes Paykend", desc: "Die Ruinen einer der größten Städte der Oase Buchara, etwa 40 km südwestlich von Buchara. Paykend hieß die „Stadt der Kaufleute“: Sie lag an der Karawanenstraße und kam ohne eigenen Herrscher aus. 706 belagerte und eroberte sie der arabische Feldherr Qutayba ibn Muslim, und bis zum 11. Jahrhundert erlosch hier das Leben. Seit 1981 legen Archäologen der Eremitage und Usbekistans Zitadelle, Mauern, Straßen und eine der ältesten Moscheen der Region frei. Daneben steht ein Fundmuseum." },
    fr: { name: "Paykend antique", desc: "Les ruines de l'une des plus grandes villes de l'oasis de Boukhara, à environ 40 km au sud-ouest de Boukhara. Paykend était appelée la « ville des marchands » : située sur la route caravanière, elle se passait de souverain propre. En 706, le général arabe Qoutaïba ibn Mouslim l'assiégea et la prit, et au XIe siècle la vie s'y éteignit. Depuis 1981, des archéologues de l'Ermitage et d'Ouzbékistan ont dégagé citadelle, remparts, rues et l'une des plus anciennes mosquées de la région. Un musée des trouvailles se trouve à côté." },
    ja: { name: "古代パイケンド", desc: "ブハラの南西約40kmにある、ブハラ・オアシス最大級の都市の遺跡です。パイケンドは隊商路沿いにあり、独自の支配者なしで治められた「商人の町」と呼ばれました。706年、アラブの将軍クタイバ・イブン・ムスリムが包囲して攻略し、11世紀までに町の生活は途絶えました。1981年からエルミタージュとウズベキスタンの考古学者が城塞、城壁、街路、地域最古級のモスクを発掘しています。近くに出土品の博物館があります。" },
    tr: { name: "Antik Paykent", desc: "Buhara'nın yaklaşık 40 km güneybatısında, Buhara vahasının en büyük kentlerinden birinin kalıntıları. Paykent “tüccarlar şehri” diye anılırdı: kervan yolu üzerindeydi ve kendi hükümdarı olmadan yönetilirdi. 706'da Arap komutan Kuteybe bin Müslim kenti kuşatıp aldı; 11. yüzyıla gelindiğinde hayat sönmüştü. 1981'den beri Ermitaj ve Özbekistan arkeologları iç kaleyi, surları, sokakları ve bölgenin en eski camilerinden birini ortaya çıkarıyor. Yakınında bir buluntu müzesi vardır." },
    ar: { name: "بيكند القديمة", desc: "أطلال إحدى أكبر مدن واحة بخارى، على بعد نحو 40 كم جنوب غرب بخارى. كانت بيكند تُسمى «مدينة التجار»: قامت على طريق القوافل وأُديرت دون حاكم خاص بها. في عام 706 حاصرها القائد العربي قتيبة بن مسلم وفتحها، وبحلول القرن الحادي عشر انطفأت الحياة فيها. ومنذ 1981 يكشف علماء آثار من الأرميتاج وأوزبكستان عن القلعة والأسوار والشوارع وأحد أقدم المساجد في المنطقة. وبالقرب منها متحف للّقى." },
  },
  "bx-avicenna": {
    zh: { name: "阿夫沙纳的伊本·西那博物馆", desc: "位于布哈拉以北约25公里佩什库区阿夫沙纳村的纪念博物馆——这里是阿布·阿里·伊本·西那（阿维森纳）的出生地，他于980年生于此。这位博学家、医生和哲学家，《医典》的作者，在阿夫沙纳度过了幼年，之后举家迁往布哈拉。展览通过手稿、药草和器具介绍他的生平、著作和中世纪医学。博物馆旁立有这位学者的纪念碑。" },
    ko: { name: "아프쇼나의 이븐 시나 박물관", desc: "부하라 북쪽 약 25km 페슈쿠 지구 아프쇼나 마을에 있는 기념 박물관으로, 980년 이곳에서 태어난 아부 알리 이븐 시나(아비센나)의 고향입니다. 『의학 정전』의 저자인 이 박식가이자 의사, 철학자는 어린 시절을 아프쇼나에서 보낸 뒤 가족과 함께 부하라로 이주했습니다. 전시는 필사본, 약초, 도구를 통해 그의 생애와 저작, 중세 의학을 소개합니다. 박물관 옆에는 학자의 기념비가 서 있습니다." },
    de: { name: "Avicenna-Museum in Afschona", desc: "Ein Gedenkmuseum im Dorf Afschona im Bezirk Peschku, etwa 25 km nördlich von Buchara – dem Geburtsort von Abu Ali ibn Sina (Avicenna), der hier 980 zur Welt kam. Der Universalgelehrte, Arzt und Philosoph, Verfasser des „Kanons der Medizin“, verbrachte seine frühe Kindheit in Afschona, bevor die Familie nach Buchara zog. Die Ausstellung zeigt sein Leben, seine Werke und die Medizin des Mittelalters anhand von Handschriften, Heilkräutern und Instrumenten. Neben dem Museum steht ein Denkmal des Gelehrten." },
    fr: { name: "Musée d'Avicenne à Afchona", desc: "Un musée mémorial au village d'Afchona, district de Pechkou, à environ 25 km au nord de Boukhara – lieu de naissance d'Abou Ali ibn Sina (Avicenne), né ici en 980. Le savant universel, médecin et philosophe, auteur du « Canon de la médecine », passa sa petite enfance à Afchona avant que sa famille ne s'installe à Boukhara. L'exposition présente sa vie, ses œuvres et la médecine médiévale à travers manuscrits, plantes médicinales et instruments. Un monument au savant se dresse à côté du musée." },
    ja: { name: "アフショナのイブン・シーナー博物館", desc: "ブハラの北約25km、ペシュク地区アフショナ村にある記念博物館で、980年にこの地で生まれたアブー・アリー・イブン・シーナー（アヴィセンナ）の生誕地です。『医学典範』の著者でもあるこの博学者・医師・哲学者は、幼少期をアフショナで過ごしたのち家族とブハラへ移りました。展示は写本、薬草、器具を通して、彼の生涯と著作、中世の医学を紹介します。博物館の隣には学者の記念碑が立っています。" },
    tr: { name: "Afşana'daki İbn Sina Müzesi", desc: "Buhara'nın yaklaşık 25 km kuzeyinde, Peşku ilçesindeki Afşana köyünde bir anı müzesi – 980'de burada doğan Ebu Ali İbn Sina'nın (Avicenna) doğum yeri. “Tıbbın Kanunu”nun yazarı olan bu çok yönlü âlim, hekim ve filozof, ilk çocukluğunu Afşana'da geçirdi, sonra ailesi Buhara'ya taşındı. Sergi el yazmaları, şifalı bitkiler ve aletlerle onun hayatını, eserlerini ve Orta Çağ tıbbını anlatır. Müzenin yanında âlimin anıtı durur." },
    ar: { name: "متحف ابن سينا في أفشنة", desc: "متحف تذكاري في قرية أفشنة بمنطقة بيشكو على بعد نحو 25 كم شمال بخارى – مسقط رأس أبي علي ابن سينا الذي وُلد هنا عام 980. قضى هذا العالم الموسوعي والطبيب والفيلسوف، صاحب «القانون في الطب»، طفولته الأولى في أفشنة قبل أن تنتقل أسرته إلى بخارى. يعرض المعرض حياته ومؤلفاته وطب العصور الوسطى من خلال المخطوطات والأعشاب الطبية والأدوات. وبجانب المتحف نصب تذكاري للعالِم." },
  },
  "bx-revgari": {
    zh: { name: "霍贾·阿里夫·雷夫加里陵墓", desc: "位于布哈拉以北约40公里沙菲尔孔区的纪念建筑群，在被称为“莫希托本”（意为“如月般闪耀”）的霍贾·阿里夫·雷夫加里墓旁。他是阿卜杜哈利克·吉日杜瓦尼的弟子，布哈拉“七圣”中的第二位，其精神传承延续到纳克什班迪教团。建筑群为朝圣者修建，有陵墓、清真寺和礼拜庭院。通常与吉日杜万、瓦布肯特一起列入“七位导师”之路参观。" },
    ko: { name: "호자 아리프 레브가리 영묘", desc: "부하라 북쪽 약 40km 쇼피르콘 지구에 있는 기념 단지로, ‘달처럼 빛나는 이’라는 뜻의 모히토본이라 불린 호자 아리프 레브가리의 묘 옆에 있습니다. 압둘할리크 기즈두바니의 제자로 부하라 ‘일곱 성인’ 중 둘째이며, 그의 영적 계보는 낙시반디 교단으로 이어졌습니다. 영묘, 모스크, 예배 마당을 갖춘 순례지입니다. 보통 ‘일곱 피르’ 순례에서 기즈두반, 보브켄트와 함께 들릅니다." },
    de: { name: "Mausoleum Chodscha Arif Revgari", desc: "Ein Gedenkkomplex im Bezirk Schofirkon, etwa 40 km nördlich von Buchara, am Grab von Chodscha Arif Revgari, genannt Mohitobon, „leuchtend wie der Mond“. Als Schüler Abdulchaliq Gijduvanis ist er der zweite der „sieben Heiligen“ Bucharas, dessen geistige Linie im Naqschbandi-Orden fortlebte. Der Komplex ist für Pilger angelegt, mit Mausoleum, Moschee und Gebetshof. Meist wird er zusammen mit Gijduvon und Vobkent auf der Route der „sieben Pire“ besucht." },
    fr: { name: "Mausolée de Khodja Arif Revgari", desc: "Un complexe mémorial du district de Chofirkon, à environ 40 km au nord de Boukhara, près de la tombe de Khodja Arif Revgari, dit Mohitobon, « brillant comme la lune ». Disciple d'Abdoulkhaliq Guijdouvani, il est le deuxième des « sept saints » de Boukhara, dont la lignée spirituelle se poursuivit dans l'ordre Naqchbandi. Le complexe est aménagé pour les pèlerins, avec mausolée, mosquée et cour de prière. On le visite généralement avec Guijdouvan et Vobkent sur la route des « sept pirs »." },
    ja: { name: "ホジャ・アリフ・レヴガリー廟", desc: "ブハラの北約40kmのショフィルコン地区にある記念建築群で、「月のように輝く者」を意味するモヒトボンと呼ばれたホジャ・アリフ・レヴガリーの墓のそばにあります。アブドゥルハリク・ギジュドゥヴァーニーの弟子で、ブハラの「七聖人」の二人目にあたり、その霊的系譜はナクシュバンディー教団へ受け継がれました。霊廟、モスク、礼拝の中庭を備えた巡礼地です。たいていギジュドゥヴァン、ヴォブケントとともに「七人のピール」巡りで訪れます。" },
    tr: { name: "Hoca Arif Rivgeri Türbesi", desc: "Buhara'nın yaklaşık 40 km kuzeyinde, Şofirkon ilçesinde, “ay gibi parlayan” anlamında Mahitaban diye anılan Hoca Arif Rivgeri'nin kabri yanındaki anıt külliye. Abdülhalık Gücdüvani'nin müridi olan bu zat, Buhara'nın “yedi velisi”nin ikincisidir ve manevi silsilesi Nakşibendilikte devam etti. Külliye ziyaretçiler için düzenlenmiştir: türbe, cami ve namaz avlusu. Genellikle “yedi pir” yolunda Gijduvan ve Vabkent ile birlikte ziyaret edilir." },
    ar: { name: "ضريح خواجه عارف الريوكري", desc: "مجمع تذكاري في منطقة شافيركان على بعد نحو 40 كم شمال بخارى، عند قبر خواجه عارف الريوكري الملقب بـ«ماهي تابان» أي «المشرق كالقمر». كان تلميذ عبد الخالق الغجدواني، وهو ثاني «الأولياء السبعة» في بخارى، واستمرت سلسلته الروحية في الطريقة النقشبندية. أُعدّ المجمع للزوار، وفيه الضريح ومسجد وفناء للصلاة. ويُزار عادة مع غجدوان ووابكنت ضمن مسار «البيرات السبعة»." },
  },
  "bx-amirkulol": {
    zh: { name: "赛义德·阿米尔·库洛尔纪念建筑群", desc: "位于布哈拉以东约12公里卡甘区的纪念建筑群，在布哈拉“七圣”之一赛义德·阿米尔·库洛尔（卒于1370年）墓旁。他的绰号“库洛尔”意为“陶工”，来自他谋生的手艺。阿米尔·库洛尔是巴哈丁·纳克什班德的精神导师，据传也是少年阿米尔·帖木儿的导师。这座带陵墓、清真寺和林荫庭院的建筑群属于“七位导师”路线，人们常在前往纳克什班德纪念建筑群途中顺路参观。" },
    ko: { name: "사이이드 아미르 쿨롤 기념 단지", desc: "부하라 동쪽 약 12km 카간 지구에 있는 기념 단지로, 부하라 ‘일곱 성인’ 중 하나인 사이이드 아미르 쿨롤(1370년 별세)의 묘 옆에 있습니다. ‘도공’이라는 뜻의 별명 쿨롤은 그가 생계를 꾸린 기술에서 비롯되었습니다. 아미르 쿨롤은 바하우딘 낙시반드의 영적 스승이었고, 전승에 따르면 젊은 아미르 티무르의 스승이기도 했습니다. 영묘, 모스크, 그늘진 안뜰을 갖춘 이곳은 ‘일곱 피르’ 순례에 속해 낙시반드 기념 단지로 가는 길에 흔히 들릅니다." },
    de: { name: "Gedenkstätte Sayyid Amir Kulol", desc: "Ein Gedenkkomplex im Bezirk Kagan, etwa 12 km östlich von Buchara, am Grab von Sayyid Amir Kulol (gest. 1370), einem der „sieben Heiligen“ Bucharas. Sein Beiname Kulol, „Töpfer“, stammt vom Handwerk, mit dem er seinen Lebensunterhalt verdiente. Amir Kulol war der geistige Lehrer Bahauddin Naqschbands und der Überlieferung nach auch des jungen Amir Timur. Der Komplex mit Mausoleum, Moschee und schattigem Hof gehört zur Route der „sieben Pire“ und wird oft auf dem Weg zur Naqschband-Gedenkstätte besucht." },
    fr: { name: "Mémorial de Sayyid Amir Koulol", desc: "Un complexe mémorial du district de Kagan, à environ 12 km à l'est de Boukhara, près de la tombe de Sayyid Amir Koulol (mort en 1370), l'un des « sept saints » de Boukhara. Son surnom Koulol, « potier », vient du métier dont il vivait. Amir Koulol fut le maître spirituel de Bahaouddin Naqchband et, selon la tradition, du jeune Amir Timour. Le complexe avec mausolée, mosquée et cour ombragée fait partie de la route des « sept pirs » et se visite souvent en chemin vers le mémorial de Naqchband." },
    ja: { name: "サイイド・アミール・クロル記念建築群", desc: "ブハラの東約12kmのカガン地区にある記念建築群で、ブハラの「七聖人」の一人サイイド・アミール・クロル（1370年没）の墓のそばにあります。「陶工」を意味するクロルというあだ名は、彼が生計を立てた技に由来します。アミール・クロルはバハウッディーン・ナクシュバンドの霊的な師であり、伝承では若きアミール・ティムールの師でもありました。霊廟、モスク、木陰の中庭のあるこの地は「七人のピール」巡りの一部で、ナクシュバンド廟へ向かう途中によく立ち寄られます。" },
    tr: { name: "Seyyid Emir Külal Anıt Külliyesi", desc: "Buhara'nın yaklaşık 12 km doğusunda, Kagan ilçesinde, Buhara'nın “yedi velisi”nden Seyyid Emir Külal'ın (ö. 1370) kabri yanındaki anıt külliye. “Çömlekçi” anlamına gelen Külal lakabı, geçimini sağladığı zanaattan gelir. Emir Külal, Bahaeddin Nakşibend'in manevi hocasıydı ve rivayete göre genç Emir Timur'un da hocasıydı. Türbe, cami ve gölgeli avludan oluşan külliye “yedi pir” yolunun parçasıdır ve sıkça Nakşibend külliyesine giderken ziyaret edilir." },
    ar: { name: "مجمع السيد أمير كلال التذكاري", desc: "مجمع تذكاري في منطقة كاغان على بعد نحو 12 كم شرق بخارى، عند قبر السيد أمير كلال (توفي 1370)، أحد «الأولياء السبعة» في بخارى. لقبه «كلال» أي «الفخّار» مأخوذ من الحرفة التي كسب منها رزقه. كان أمير كلال المعلم الروحي لبهاء الدين نقشبند، وبحسب الرواية معلم أمير تيمور في شبابه أيضًا. والمجمع بضريحه ومسجده وفنائه الظليل جزء من مسار «البيرات السبعة»، ويُزار غالبًا في الطريق إلى مجمع نقشبند." },
  },
  "bx-kalyanmosque": {
    zh: { name: "卡扬清真寺", desc: "布哈拉的聚礼清真寺，位于卡扬宣礼塔脚下，1514年昔班尼王朝时期在12世纪喀喇汗清真寺的旧址上建成。它是中亚最大的清真寺之一：巨大的庭院四周环绕着由立柱支撑、覆盖着288个小穹顶的回廊，主殿上方耸立着绿松石色穹顶。庭院里可容纳上万人同时礼拜。苏联时期这里曾被用作仓库，如今重新成为使用中的清真寺。请在礼拜时间以外参观，并穿着得体。" },
    ko: { name: "칼론 모스크", desc: "칼론 미나렛 발치에 있는 부하라의 금요 모스크로, 1514년 샤이반 왕조 때 12세기 카라한 왕조 모스크 터에 지어졌습니다. 중앙아시아 최대급 모스크로, 거대한 안뜰을 기둥 위 288개의 작은 돔으로 덮인 회랑이 둘러싸고, 본당 위로 청록색 돔이 솟아 있습니다. 안뜰에서 최대 1만 명이 예배할 수 있었습니다. 소련 시대에는 창고로 쓰였고, 지금은 다시 예배가 열리는 모스크입니다. 예배 시간을 피해 단정한 차림으로 방문하세요." },
    de: { name: "Kalon-Moschee", desc: "Bucharas Freitagsmoschee am Fuß des Kalon-Minaretts, 1514 unter den Schaibaniden an der Stelle einer karachanidischen Moschee des 12. Jahrhunderts erbaut. Sie zählt zu den größten Moscheen Zentralasiens: Ein riesiger Hof ist von Galerien mit 288 kleinen Kuppeln auf Pfeilern umgeben, über dem Hauptsaal erhebt sich eine türkisfarbene Kuppel. Bis zu zehntausend Menschen konnten im Hof beten. In Sowjetzeiten diente sie als Lager, heute ist sie wieder eine aktive Moschee. Außerhalb der Gebetszeiten und zurückhaltend gekleidet besuchen." },
    fr: { name: "Mosquée Kalian", desc: "La mosquée du vendredi de Boukhara, au pied du minaret Kalian, bâtie en 1514 sous les Chaybanides à l'emplacement d'une mosquée karakhanide du XIIe siècle. C'est l'une des plus grandes mosquées d'Asie centrale : une immense cour est entourée de galeries couvertes de 288 petites coupoles sur piliers, et une coupole turquoise s'élève au-dessus de la salle principale. Jusqu'à dix mille personnes pouvaient prier dans la cour. Entrepôt à l'époque soviétique, c'est de nouveau une mosquée active. Visitez en dehors des heures de prière, en tenue correcte." },
    ja: { name: "カラン・モスク", desc: "カラン・ミナレットの足元にあるブハラの金曜モスクで、1514年にシャイバーン朝のもと、12世紀のカラハン朝のモスクの跡に建てられました。中央アジア最大級のモスクで、巨大な中庭を柱の上の288の小さなドームで覆われた回廊が囲み、主礼拝堂の上にはターコイズのドームがそびえます。中庭では最大1万人が礼拝できました。ソ連時代には倉庫とされましたが、今は再び現役のモスクです。礼拝時間外に、控えめな服装で訪れてください。" },
    tr: { name: "Kalan Camii", desc: "Kalan Minaresi'nin dibinde Buhara'nın Cuma camii; 1514'te Şeybaniler döneminde 12. yüzyıl Karahanlı camisinin yerine yapıldı. Orta Asya'nın en büyük camilerinden biridir: dev avluyu sütunlar üzerinde 288 küçük kubbeyle örtülü revaklar çevreler, ana salonun üzerinde turkuaz bir kubbe yükselir. Avluda on bine kadar kişi namaz kılabilirdi. Sovyet döneminde depo olarak kullanıldı; bugün yeniden faal bir camidir. Namaz vakitleri dışında ve kapalı giyinerek ziyaret edin." },
    ar: { name: "مسجد كلان", desc: "مسجد الجمعة في بخارى عند قدم مئذنة كلان، بُني عام 1514 في عهد الشيبانيين مكان مسجد قراخاني من القرن الثاني عشر. وهو من أكبر مساجد آسيا الوسطى: تحيط بفنائه الضخم أروقة تغطيها 288 قبة صغيرة على أعمدة، وتعلو القاعةَ الرئيسية قبةٌ فيروزية. كان الفناء يتسع لعشرة آلاف مصلٍّ. استُخدم مستودعًا في العهد السوفيتي، وعاد اليوم مسجدًا قائمًا. زُره خارج أوقات الصلاة وبملابس محتشمة." },
  },
  "bx-kogonpalace": {
    zh: { name: "卡甘的埃米尔行宫", desc: "布哈拉埃米尔阿卜杜拉哈德汗在卡甘的宫殿——卡甘即19世纪末在火车站旁发展起来的“新布哈拉”。埃米尔修建它，是为了在这里接待乘坐外里海铁路前来的俄国宾客和官员。设计被认为出自建筑师阿列克谢·贝努瓦之手：带灰泥装饰和小塔楼的欧式外立面与内部的东方装饰相结合。这是乌兹别克斯坦罕见的“殖民地新艺术风格”建筑——与西托莱·莫希·霍萨宫对比很有意思。" },
    ko: { name: "카간의 에미르 여행 궁전", desc: "19세기 말 기차역 옆에 생겨난 ‘신부하라’ 카간에 있는 부하라 에미르 압둘라하드 칸의 궁전입니다. 에미르는 카스피해 횡단 철도로 오는 러시아 손님과 관리들을 맞이하려고 이 궁전을 지었습니다. 설계는 건축가 알렉세이 베누아의 것으로 알려져 있으며, 회반죽 장식과 작은 탑을 갖춘 유럽식 외관이 동양풍 실내 장식과 어우러집니다. 우즈베키스탄에서 드문 ‘식민지 아르누보’의 예로, 시토라이 모히 호사와 비교해 보면 흥미롭습니다." },
    de: { name: "Reisepalast des Emirs in Kagan", desc: "Der Palast des Emirs von Buchara Abdulahad Khan in Kagan – Neu-Buchara, das Ende des 19. Jahrhunderts am Bahnhof entstand. Der Emir ließ ihn bauen, um hier russische Gäste und Beamte zu empfangen, die mit der Transkaspischen Eisenbahn kamen. Der Entwurf wird dem Architekten Alexander Benois zugeschrieben: Europäische Fassaden mit Stuck und Türmchen verbinden sich mit orientalischem Schmuck im Inneren. Ein seltenes Beispiel für „kolonialen Jugendstil“ in Usbekistan – spannend im Vergleich mit Sitorai Mochi-Chosa." },
    fr: { name: "Palais de voyage de l'émir à Kagan", desc: "Le palais de l'émir de Boukhara Abdoulakhad Khan à Kagan – la Nouvelle Boukhara, née près de la gare à la fin du XIXe siècle. L'émir le fit construire pour y recevoir les hôtes et fonctionnaires russes arrivant par le chemin de fer transcaspien. Le projet est attribué à l'architecte Alexeï Benois : façades européennes à stucs et tourelles, décor oriental à l'intérieur. Un rare exemple d'« Art nouveau colonial » en Ouzbékistan – intéressant à comparer avec Sitoraï Mokhi-Khossa." },
    ja: { name: "カガンのアミールの離宮", desc: "19世紀末に駅のそばに生まれた「新ブハラ」カガンにある、ブハラのアミール、アブドゥルアハド・ハンの宮殿です。アミールは、ザカスピ鉄道でやって来るロシアの客や役人をここで迎えるために建てました。設計は建築家アレクセイ・ベヌアによるとされ、漆喰装飾と小塔のあるヨーロッパ風の外観と、東洋風の室内装飾が組み合わさっています。ウズベキスタンでは珍しい「植民地アールヌーヴォー」の例で、シトライ・マヒ・ホサ宮殿と比べてみると興味深いです。" },
    tr: { name: "Kagan'daki Emirin Yol Sarayı", desc: "Buhara Emiri Abdülahad Han'ın, 19. yüzyıl sonunda tren istasyonunun yanında gelişen Yeni Buhara – Kagan'daki sarayı. Emir onu, Hazar Ötesi Demiryolu ile gelen Rus misafirlerini ve memurlarını burada ağırlamak için yaptırdı. Tasarımı mimar Aleksey Benua'ya atfedilir: alçı süslemeli ve kuleli Avrupai cepheler, içerideki Doğu süslemeleriyle birleşir. Özbekistan'da nadir bir “sömürge Art Nouveau” örneği – Sitorai Mohi Hasa ile karşılaştırmak ilginçtir." },
    ar: { name: "قصر الأمير للسفر في كاغان", desc: "قصر أمير بخارى عبد الأحد خان في كاغان – «بخارى الجديدة» التي نشأت بجوار محطة القطار في أواخر القرن التاسع عشر. بناه الأمير لاستقبال الضيوف والمسؤولين الروس القادمين بسكة حديد ما وراء قزوين. يُنسب تصميمه إلى المعماري أليكسي بينوا: واجهات أوروبية بزخارف جصية وأبراج صغيرة تمتزج بزخرفة شرقية في الداخل. مثال نادر على «الآرت نوفو الاستعماري» في أوزبكستان – ومقارنته بقصر ستوراي ماهي خاصه مثيرة للاهتمام." },
  },
  "bx-anjirfagnavi": {
    zh: { name: "马哈茂德·安吉尔·法格纳维建筑群", desc: "瓦布肯特区安吉尔博格村的朝圣地，在13世纪苏菲导师马哈茂德·安吉尔·法格纳维墓旁——他是布哈拉“七位导师”中的第三位，霍贾·阿里夫·雷夫加里的弟子。他传授高声念诵的齐克尔，延续了后来通向巴哈丁·纳克什班德的精神传承。1999–2000年墓上新建了陵墓，旁边有带廊台的清真寺、水池和朝圣者庭院。通常在“七位导师”路线中参观；请穿着得体。" },
    ko: { name: "마흐무드 안지르 파그나비 단지", desc: "보브켄트 지구 안지르보그 마을에 있는 순례지로, 부하라 ‘일곱 피르’ 중 셋째이자 호자 아리프 레브가리의 제자인 13세기 수피 스승 마흐무드 안지르 파그나비의 묘 옆에 있습니다. 그는 소리 내어 하는 지크르를 가르쳤고, 훗날 바하우딘 낙시반드로 이어지는 영적 계보를 잇게 했습니다. 1999~2000년 묘 위에 새 영묘가 세워졌고, 옆에는 아이반이 있는 모스크, 연못, 순례자 마당이 있습니다. 보통 ‘일곱 피르’ 순례 중에 들르며, 단정하게 입으세요." },
    de: { name: "Komplex Mahmud Andschir Faghnavi", desc: "Eine Pilgerstätte im Dorf Andschirbog im Bezirk Vobkent, am Grab des Sufi-Meisters Mahmud Andschir Faghnavi aus dem 13. Jahrhundert, des dritten der „sieben Pire“ Bucharas und Schülers von Chodscha Arif Revgari. Er lehrte den lauten Dhikr und führte die geistige Kette fort, die später zu Bahauddin Naqschband führte. 1999–2000 wurde über dem Grab ein neues Mausoleum errichtet, daneben eine Moschee mit Aiwanen, ein Teich und ein Pilgerhof. Meist auf der Route der „sieben Pire“ besucht; zurückhaltend kleiden." },
    fr: { name: "Complexe de Mahmoud Andjir Faghnavi", desc: "Un lieu de pèlerinage au village d'Andjirbog, district de Vobkent, près de la tombe du maître soufi du XIIIe siècle Mahmoud Andjir Faghnavi, troisième des « sept pirs » de Boukhara et disciple de Khodja Arif Revgari. Il enseigna le dhikr à voix haute et prolongea la chaîne spirituelle qui mena plus tard à Bahaouddin Naqchband. En 1999–2000, un nouveau mausolée fut construit sur la tombe, avec à côté une mosquée à aïvans, un bassin et une cour pour les pèlerins. On le visite généralement sur la route des « sept pirs » ; tenue correcte." },
    ja: { name: "マフムード・アンジル・ファグナヴィー建築群", desc: "ヴォブケント地区アンジルボグ村にある巡礼地で、ブハラの「七人のピール」の三人目でホジャ・アリフ・レヴガリーの弟子だった13世紀のスーフィーの師、マフムード・アンジル・ファグナヴィーの墓のそばにあります。彼は声に出して唱えるズィクルを教え、のちにバハウッディーン・ナクシュバンドへ至る霊的系譜を受け継ぎました。1999～2000年に墓の上に新しい霊廟が建てられ、隣にはアイヴァンのあるモスク、池、巡礼者の中庭があります。たいてい「七人のピール」巡りで訪れます。控えめな服装で。" },
    tr: { name: "Mahmud Encir Fağnevi Külliyesi", desc: "Vabkent ilçesinin Encirbağ köyünde, Buhara'nın “yedi piri”nin üçüncüsü ve Hoca Arif Rivgeri'nin müridi olan 13. yüzyıl sufi üstadı Mahmud Encir Fağnevi'nin kabri yanındaki ziyaretgâh. Sesli zikri öğretti ve daha sonra Bahaeddin Nakşibend'e varan manevi silsileyi sürdürdü. 1999–2000'de kabrin üzerine yeni bir türbe yapıldı; yanında eyvanlı bir cami, havuz ve ziyaretçi avlusu vardır. Genellikle “yedi pir” yolunda ziyaret edilir; kapalı giyinin." },
    ar: { name: "مجمع محمود أنجير فغنوي", desc: "مزار في قرية أنجيرباغ بمنطقة وابكنت، عند قبر الشيخ الصوفي محمود أنجير فغنوي من القرن الثالث عشر، ثالث «البيرات السبعة» في بخارى وتلميذ خواجه عارف الريوكري. علّم الذكر الجهري وواصل السلسلة الروحية التي قادت لاحقًا إلى بهاء الدين نقشبند. بُني فوق القبر بين 1999 و2000 ضريح جديد، وبجانبه مسجد بأواوين وحوض وفناء للزوار. يُزار عادة ضمن مسار «البيرات السبعة»؛ ارتدِ ملابس محتشمة." },
  },
  "bx-romitani": {
    zh: { name: "哈兹拉提·阿齐宗（阿里·拉米塔尼）建筑群", desc: "罗米坦镇的一处圣地，与13至14世纪的苏菲霍贾·阿里·拉米塔尼有关，人们尊称他为“哈兹拉提·阿齐宗”，意为“圣中之圣”。他是布哈拉“七位导师”之一，相传是一名织工，教导人们通往真主之路在于诚实劳动和为人服务。这座带陵墓、清真寺和林荫庭院的纪念建筑群是瓦布肯特与布哈拉之间“七位导师”路线上的重要一站。请穿着得体；女士应包头巾。" },
    ko: { name: "하즈라티 아지존(알리 라미타니) 단지", desc: "로미탄 시에 있는 성지로, ‘성인 중의 성인’이라는 뜻의 하즈라티 아지존으로 공경받은 13~14세기 수피 호자 알리 라미타니와 관련이 있습니다. 부하라 ‘일곱 피르’ 중 하나로, 전승에 따르면 직조공이었으며 신에게 이르는 길은 정직한 노동과 사람들에 대한 봉사를 통한다고 가르쳤습니다. 영묘, 모스크, 그늘진 안뜰을 갖춘 기념 단지는 보브켄트와 부하라 사이 ‘일곱 피르’ 순례의 중요한 정거장입니다. 단정하게 입고, 여성은 머리를 가리세요." },
    de: { name: "Komplex Hazrati Azizon (Ali Ramitani)", desc: "Ein Heiligtum in der Stadt Romitan, verbunden mit dem Sufi Chodscha Ali Ramitani aus dem 13.–14. Jahrhundert, ehrfürchtig Hazrati Azizon genannt, „Heiliger der Heiligen“. Als einer der „sieben Pire“ Bucharas war er der Überlieferung nach Weber und lehrte, dass der Weg zu Gott über ehrliche Arbeit und Dienst an den Menschen führt. Der Gedenkkomplex mit Mausoleum, Moschee und schattigem Hof ist ein wichtiger Halt der Route der „sieben Pire“ zwischen Vobkent und Buchara. Zurückhaltend kleiden; Frauen bedecken das Haar." },
    fr: { name: "Complexe Hazrati Azizon (Ali Ramitani)", desc: "Un sanctuaire de la ville de Romitan lié au soufi des XIIIe–XIVe siècles Khodja Ali Ramitani, respectueusement appelé Hazrati Azizon, « saint des saints ». L'un des « sept pirs » de Boukhara, il était selon la tradition tisserand et enseignait que le chemin vers Dieu passe par le travail honnête et le service aux autres. Le complexe mémorial avec mausolée, mosquée et cour ombragée est une étape importante de la route des « sept pirs » entre Vobkent et Boukhara. Tenue correcte ; les femmes se couvrent les cheveux." },
    ja: { name: "ハズラティ・アズィゾン（アリー・ラミターニー）建築群", desc: "ロミタンの町にある聖地で、「聖者の中の聖者」を意味するハズラティ・アズィゾンと敬われた13～14世紀のスーフィー、ホジャ・アリー・ラミターニーゆかりの地です。ブハラの「七人のピール」の一人で、伝承では織工であり、神への道は誠実な労働と人々への奉仕を通じて開かれると説きました。霊廟、モスク、木陰の中庭のある記念建築群は、ヴォブケントとブハラの間の「七人のピール」巡りの重要な立ち寄り先です。控えめな服装で、女性は髪を覆ってください。" },
    tr: { name: "Hazreti Azizan (Ali Ramitani) Külliyesi", desc: "Romitan kasabasında, “velilerin velisi” anlamında Hazreti Azizan diye saygıyla anılan 13.–14. yüzyıl sufisi Hoca Ali Ramitani ile ilişkili bir ziyaretgâh. Buhara'nın “yedi piri”nden biri olan bu zat, rivayete göre dokumacıydı ve Allah'a giden yolun dürüst emek ve insanlara hizmetten geçtiğini öğretti. Türbe, cami ve gölgeli avludan oluşan anıt külliye, Vabkent ile Buhara arasındaki “yedi pir” yolunun önemli bir durağıdır. Kapalı giyinin; kadınlar başını örtmeli." },
    ar: { name: "مجمع حضرتي عزيزان (علي الراميتني)", desc: "مزار في بلدة روميتان يرتبط بالصوفي خواجه علي الراميتني من القرنين الثالث عشر والرابع عشر، الملقب تبجيلًا بـ«حضرتي عزيزان» أي «ولي الأولياء». وهو أحد «البيرات السبعة» في بخارى، وكان بحسب الرواية حائكًا، وعلّم أن الطريق إلى الله يمر بالعمل الصادق وخدمة الناس. والمجمع التذكاري بضريحه ومسجده وفنائه الظليل محطة مهمة في مسار «البيرات السبعة» بين وابكنت وبخارى. ارتدِ ملابس محتشمة، وعلى النساء تغطية الشعر." },
  },
};
